template/napi_features.mbt:
///|
/// Promise support is available in Node-API v1.
pub fn napi_promise_new(env : NapiEnv) -> NapiPromise raise NapiError {
  let deferred = Ref(moonbit_dummy_deferred())
  let promise = Ref(moonbit_dummy_napi_value())
  let status = napi_create_promise(env, deferred, promise)
  result_from_status(env, status, b"Failed to create Promise")
  { promise: promise.val, deferred: deferred.val, settled: false, }
}

///|
pub fn napi_promise_resolve(
  env : NapiEnv,
  promise : NapiPromise,
  value : NapiValue,
) -> Unit raise NapiError {
  if promise.settled {
    raise napi_failure(
      1,
      Error,
      "ERR_NAPI_PROMISE_SETTLED",
      "Promise has already settled",
    )
  }
  promise.settled = true
  let status = napi_resolve_deferred(env, promise.deferred, value)
  result_from_status(env, status, b"Failed to resolve Promise")
}

///|
pub fn napi_promise_reject(
  env : NapiEnv,
  promise : NapiPromise,
  reason : NapiValue,
) -> Unit raise NapiError {
  if promise.settled {
    raise napi_failure(
      1,
      Error,
      "ERR_NAPI_PROMISE_SETTLED",
      "Promise has already settled",
    )
  }
  promise.settled = true
  let status = napi_reject_deferred(env, promise.deferred, reason)
  result_from_status(env, status, b"Failed to reject Promise")
}

///|
/// Returns whether a value is a JavaScript Promise.
pub fn napi_promise_is(
  env : NapiEnv,
  value : NapiValue,
) -> Bool raise NapiError {
  let result = Ref(false)
  let status = napi_is_promise(env, value, result)
  result_from_status(env, status, b"Failed to inspect Promise")
  result.val
}

///|
pub fn napi_bigint_from_int64(
  env : NapiEnv,
  value : Int64,
) -> NapiValue raise NapiError {
  let result = Ref(moonbit_dummy_napi_value())
  let status = napi_create_bigint_int64(env, value, result)
  result_from_status(env, status, b"Failed to create BigInt")
  result.val
}

///|
pub fn napi_bigint_from_uint64(
  env : NapiEnv,
  value : UInt64,
) -> NapiValue raise NapiError {
  let result = Ref(moonbit_dummy_napi_value())
  let status = napi_create_bigint_uint64(env, value, result)
  result_from_status(env, status, b"Failed to create BigInt")
  result.val
}

///|
/// Reads a signed BigInt and returns the value plus the lossless flag.
pub fn napi_bigint_to_int64(
  env : NapiEnv,
  value : NapiValue,
) -> (Int64, Bool) raise NapiError {
  let result = Ref(0L)
  let lossless = Ref(false)
  let status = napi_get_value_bigint_int64(env, value, result, lossless)
  result_from_status(env, status, b"Failed to read BigInt")
  (result.val, lossless.val)
}

///|
/// Reads an unsigned BigInt and returns the value plus the lossless flag.
pub fn napi_bigint_to_uint64(
  env : NapiEnv,
  value : NapiValue,
) -> (UInt64, Bool) raise NapiError {
  let result = Ref(0UL)
  let lossless = Ref(false)
  let status = napi_get_value_bigint_uint64(env, value, result, lossless)
  result_from_status(env, status, b"Failed to read BigInt")
  (result.val, lossless.val)
}

///|
/// Threadsafe Function lifecycle helper. Threadsafe Functions require N-API v4.
pub fn napi_threadsafe_function_release(
  func : NapiThreadsafeFunction,
  mode : NapiTsfnReleaseMode,
) -> NapiTsfnStatus raise NapiError {
  let mode = match mode {
    Release => 0
    Abort => 1
  }
  let status = napi_release_threadsafe_function(func, mode)
  tsfn_status(status, "Failed to release Threadsafe Function")
}

///|
/// Creates a Threadsafe Function. Callback pointers are opaque unmanaged
/// pointers supplied by a C layer.
pub fn napi_threadsafe_function_create(
  env : NapiEnv,
  func : NapiValue,
  async_resource : NapiValue,
  async_resource_name : NapiValue,
  max_queue_size : Int32,
  initial_thread_count : Int32,
  finalize_data : UnmanagedBuffer,
  finalize_cb : UnmanagedBuffer,
  context : UnmanagedBuffer,
  call_js_cb : UnmanagedBuffer,
) -> NapiThreadsafeFunction raise NapiError {
  if max_queue_size < 0 || initial_thread_count <= 0 {
    raise napi_failure(
      1,
      RangeError,
      "ERR_NAPI_TSFN_OPTIONS",
      "TSFN needs nonnegative queue size and positive thread count",
    )
  }
  let result = Ref(napi_threadsafe_function_dummy())
  let status = napi_create_threadsafe_function(
    env, func, async_resource, async_resource_name, max_queue_size, initial_thread_count,
    finalize_data, finalize_cb, context, call_js_cb, result,
  )
  result_from_status(env, status, b"Failed to create Threadsafe Function")
  result.val
}

///|
pub fn napi_threadsafe_function_call(
  func : NapiThreadsafeFunction,
  data : UnmanagedBuffer,
  mode : NapiTsfnCallMode,
) -> NapiTsfnStatus raise NapiError {
  let mode = match mode {
    Nonblocking => 0
    Blocking => 1
  }
  let status = napi_call_threadsafe_function(func, data, mode)
  tsfn_status(status, "Failed to call Threadsafe Function")
}

///|
pub fn napi_threadsafe_function_acquire(
  func : NapiThreadsafeFunction,
) -> NapiTsfnStatus raise NapiError {
  let status = napi_acquire_threadsafe_function(func)
  tsfn_status(status, "Failed to acquire Threadsafe Function")
}

///|
fn tsfn_status(
  status : Int32,
  context : String,
) -> NapiTsfnStatus raise NapiError {
  match status {
    0 => Accepted
    15 => QueueFull
    16 => Closing
    _ => raise napi_failure(status, Error, "ERR_NAPI_TSFN", context)
  }
}

template/napi_runtime.mbt:
///|
let active_buffer_views : Ref[Int32] = Ref(0)

///|
pub struct NapiBufferView {
  env : NapiEnv
  value : NapiValue
  mut is_alive : Bool
}

///|
fn NapiBufferView::validate(
  self : NapiBufferView,
) -> (UnmanagedBuffer, Int32) raise NapiError {
  if !self.is_alive {
    raise napi_failure(
      1,
      Error,
      "ERR_NAPI_BUFFER_EXPIRED",
      "Buffer view is no longer valid",
    )
  }
  let data = Ref(moonbit_dummy_unmanaged_buffer())
  let len = Ref(0)
  let status = napi_get_buffer_info(self.env, self.value, data, len)
  result_from_status(
    self.env,
    status,
    b"Buffer backing store is detached or invalid",
  )
  (data.val, len.val)
}

///|
pub fn NapiBufferView::length(self : NapiBufferView) -> Int32 raise NapiError {
  self.validate().1
}

///|
pub fn NapiBufferView::load8(
  self : NapiBufferView,
  offset : Int32,
) -> Int32 raise NapiError {
  let (buf, len) = self.validate()
  if offset < 0 || offset >= len {
    raise napi_failure(
      1,
      RangeError,
      "ERR_NAPI_BUFFER_BOUNDS",
      "Buffer view out of bounds",
    )
  }
  buf.load8(offset)
}

///|
pub fn NapiBufferView::store8(
  self : NapiBufferView,
  offset : Int32,
  val : Int32,
) -> Unit raise NapiError {
  let (buf, len) = self.validate()
  if offset < 0 || offset >= len {
    raise napi_failure(
      1,
      RangeError,
      "ERR_NAPI_BUFFER_BOUNDS",
      "Buffer view out of bounds",
    )
  }
  buf.store8(offset, val)
}

///|
/// Invalidates a borrowed Buffer view after the callback returns.
pub fn NapiBufferView::invalidate(self : NapiBufferView) -> Unit {
  if self.is_alive {
    self.is_alive = false
    active_buffer_views.val -= 1
  }
}

///|
pub fn get_Int(env : NapiEnv, val : NapiValue) -> Int32 raise NapiError {
  let res = Ref(0.0)
  let status = napi_get_value_double(env, val, res)
  result_from_status(env, status, b"Invalid argument, expected Int")
  let value = res.val
  if !(value >= -2147483648.0 && value <= 2147483647.0) ||
    value != value.to_int().to_double() {
    raise napi_failure(
      1,
      RangeError,
      "ERR_NAPI_INT_RANGE",
      "Int requires a finite integral number in [-2147483648, 2147483647]",
    )
  }
  value.to_int()
}

///|
pub fn set_Int(env : NapiEnv, val : Int32) -> NapiValue raise NapiError {
  let res = Ref(moonbit_dummy_napi_value())
  let status = napi_create_int32(env, val, res)
  result_from_status(env, status, b"Failed to create Int")
  res.val
}

///|
pub fn get_UInt(env : NapiEnv, value : NapiValue) -> UInt32 raise NapiError {
  let number = get_Double(env, value)
  if !(number >= 0.0 && number <= 4294967295.0) ||
    UInt32::trunc_double(number).to_double() != number {
    raise napi_failure(
      1,
      RangeError,
      "ERR_NAPI_UINT_RANGE",
      "UInt requires a finite integer in [0, 4294967295]",
    )
  }
  UInt32::trunc_double(number)
}

///|
pub fn set_UInt(env : NapiEnv, value : UInt32) -> NapiValue raise NapiError {
  set_Double(env, value.to_double())
}

///|
pub fn get_Float(env : NapiEnv, value : NapiValue) -> Float raise NapiError {
  Float::from_double(get_Double(env, value))
}

///|
pub fn set_Float(env : NapiEnv, value : Float) -> NapiValue raise NapiError {
  set_Double(env, value.to_double())
}

///|
pub fn get_Double(env : NapiEnv, val : NapiValue) -> Double raise NapiError {
  let res = Ref(0.0)
  let status = napi_get_value_double(env, val, res)
  result_from_status(env, status, b"Invalid argument, expected Double")
  res.val
}

///|
pub fn set_Double(env : NapiEnv, val : Double) -> NapiValue raise NapiError {
  let res = Ref(moonbit_dummy_napi_value())
  let status = napi_create_double(env, val, res)
  result_from_status(env, status, b"Failed to create Double")
  res.val
}

///|
pub fn get_Bool(env : NapiEnv, val : NapiValue) -> Bool raise NapiError {
  let res = Ref(false)
  let status = napi_get_value_bool(env, val, res)
  result_from_status(env, status, b"Invalid argument, expected Bool")
  res.val
}

///|
pub fn set_Bool(env : NapiEnv, val : Bool) -> NapiValue raise NapiError {
  let res = Ref(moonbit_dummy_napi_value())
  let status = napi_get_boolean(env, val, res)
  result_from_status(env, status, b"Failed to create Bool")
  res.val
}

///|
pub fn get_String(env : NapiEnv, val : NapiValue) -> String raise NapiError {
  let status = Ref(0)
  let result = napi_read_string(env, val, status)
  result_from_status(env, status.val, b"Reading UTF-16 String")
  result
}

///|
pub fn set_String(env : NapiEnv, val : String) -> NapiValue raise NapiError {
  let res = Ref(moonbit_dummy_napi_value())
  let status = napi_write_string(env, val, res)
  result_from_status(env, status, b"Failed to create String")
  res.val
}

///|
pub fn get_Bytes(env : NapiEnv, val : NapiValue) -> Bytes raise NapiError {
  let len = Ref(0)
  let unmanaged = Ref(moonbit_dummy_unmanaged_buffer())
  let status = napi_get_buffer_info(env, val, unmanaged, len)
  result_from_status(env, status, b"Invalid argument, expected Buffer")

  napi_copy_bytes(unmanaged.val, len.val)
}

///|
pub fn set_Bytes(env : NapiEnv, val : Bytes) -> NapiValue raise NapiError {
  let res = Ref(moonbit_dummy_napi_value())
  let data = Ref(moonbit_dummy_unmanaged_buffer())
  let status = napi_create_buffer_copy(env, val.length(), val, data, res)
  result_from_status(env, status, b"Failed to create buffer")
  res.val
}

///|
pub fn get_NapiBufferView(
  env : NapiEnv,
  val : NapiValue,
) -> NapiBufferView raise NapiError {
  let len = Ref(0)
  let unmanaged = Ref(moonbit_dummy_unmanaged_buffer())
  let status = napi_get_buffer_info(env, val, unmanaged, len)
  result_from_status(env, status, b"Invalid argument, expected Buffer")
  active_buffer_views.val += 1
  { env, value: val, is_alive: true, }
}

///|
pub fn set_Unit(env : NapiEnv, _val : Unit) -> NapiValue raise NapiError {
  let res = Ref(moonbit_dummy_napi_value())
  let status = napi_get_undefined(env, res)
  result_from_status(env, status, b"Failed to create undefined")
  res.val
}

template/stub.c:
#include <node_api.h>
#include <moonbit.h>
#include <string.h>
#include <stdint.h>
#include <limits.h>
#include "napi_lifecycle.h"
#include "napi_callbacks.h"
#include "napi_owned_binary.h"

/* Shared exception boundary for C callbacks and MoonBit adapters. Never replace
 * a JS exception already pending on the environment. Every operation is checked. */
int napi_mbt_throw_status(napi_env env, int status, int kind, const char *code, const char *message) {
    bool pending = false;
    napi_status s = napi_is_exception_pending(env, &pending);
    if (s != napi_ok || pending) return (int)s;
    napi_value js_code, js_message, error, js_status;
    s = napi_create_string_utf8(env, code, NAPI_AUTO_LENGTH, &js_code);
    if (s != napi_ok) goto fallback;
    s = napi_create_string_utf8(env, message, NAPI_AUTO_LENGTH, &js_message);
    if (s != napi_ok) goto fallback;
    s = kind == 1 ? napi_create_type_error(env, js_code, js_message, &error)
      : kind == 2 ? napi_create_range_error(env, js_code, js_message, &error)
      : napi_create_error(env, js_code, js_message, &error);
    if (s != napi_ok) goto fallback;
    s = napi_create_int32(env, status, &js_status);
    if (s != napi_ok) goto fallback;
    s = napi_set_named_property(env, error, "status", js_status);
    if (s != napi_ok) goto fallback;
    s = napi_set_named_property(env, error, "context", js_message);
    if (s != napi_ok) goto fallback;
    return (int)napi_throw(env, error);
fallback:
    /* Even diagnostics can fail. Preserve any exception that caused that
     * failure; otherwise make one final attempt through the simpler API. */
    if (napi_is_exception_pending(env, &pending) != napi_ok || pending) return (int)s;
    return (int)napi_throw_error(env, code, message);
}

MOONBIT_FFI_EXPORT int moonbit_napi_throw(napi_env env, int status, int kind, const char *code, const char *message) {
    return napi_mbt_throw_status(env, status, kind, code, message);
}

#if NAPI_VERSION < 4
typedef void* napi_threadsafe_function;
#endif

MOONBIT_FFI_EXPORT
napi_value moonbit_dummy_napi_value() {
    return NULL;
}

MOONBIT_FFI_EXPORT
void* moonbit_dummy_unmanaged_buffer() {
    return NULL;
}

MOONBIT_FFI_EXPORT
void* moonbit_dummy_deferred() {
    return NULL;
}

MOONBIT_FFI_EXPORT
void* moonbit_dummy_threadsafe_function() {
    return NULL;
}

MOONBIT_FFI_EXPORT
int moonbit_napi_is_promise(napi_env env, napi_value value, int* result) {
    bool is_promise = false;
    napi_status status = napi_is_promise(env, value, &is_promise);
    if (result) *result = is_promise ? 1 : 0;
    return (int)status;
}

MOONBIT_FFI_EXPORT
int moonbit_napi_get_value_bigint_int64(napi_env env, napi_value value, int64_t* result, int* lossless) {
#if NAPI_VERSION >= 6
    bool exact = false;
    napi_status status = napi_get_value_bigint_int64(env, value, result, &exact);
    if (lossless) *lossless = exact ? 1 : 0;
    return (int)status;
#else
    (void)env; (void)value; (void)result; (void)lossless;
    return (int)napi_generic_failure;
#endif
}

MOONBIT_FFI_EXPORT
int moonbit_napi_create_bigint_int64(napi_env env, int64_t value, napi_value* result) {
#if NAPI_VERSION >= 6
    return (int)napi_create_bigint_int64(env, value, result);
#else
    (void)env; (void)value; (void)result;
    return (int)napi_generic_failure;
#endif
}

MOONBIT_FFI_EXPORT
