/* Runtime implementation, included once by stub.c. All MoonBit execution and
 * reference counting runs under this recursive lock, on a Node environment
 * thread. Background I/O code must not use these entry points. */
#ifndef NAPI_MBT_LIFECYCLE_H
#define NAPI_MBT_LIFECYCLE_H
#include <stdlib.h>
#if defined(_WIN32)
#include <windows.h>
static INIT_ONCE napi_mbt_once = INIT_ONCE_STATIC_INIT;
static CRITICAL_SECTION napi_mbt_mutex;
static BOOL CALLBACK napi_mbt_init_mutex(PINIT_ONCE once, PVOID parameter, PVOID *context) {
    (void)once; (void)parameter; (void)context;
    InitializeCriticalSection(&napi_mbt_mutex);
    return TRUE;
}
static void napi_mbt_lock(void) {
    InitOnceExecuteOnce(&napi_mbt_once, napi_mbt_init_mutex, NULL, NULL);
    EnterCriticalSection(&napi_mbt_mutex);
}
static void napi_mbt_unlock(void) { LeaveCriticalSection(&napi_mbt_mutex); }
typedef DWORD napi_mbt_thread;
static napi_mbt_thread napi_mbt_thread_self(void) { return GetCurrentThreadId(); }
static bool napi_mbt_same_thread(napi_mbt_thread a, napi_mbt_thread b) { return a == b; }
#else
#include <pthread.h>
static pthread_once_t napi_mbt_once = PTHREAD_ONCE_INIT;
static pthread_mutex_t napi_mbt_mutex;
static void napi_mbt_init_mutex(void) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&napi_mbt_mutex, &attr);
    pthread_mutexattr_destroy(&attr);
}
static void napi_mbt_lock(void) { pthread_once(&napi_mbt_once, napi_mbt_init_mutex); pthread_mutex_lock(&napi_mbt_mutex); }
static void napi_mbt_unlock(void) { pthread_mutex_unlock(&napi_mbt_mutex); }
typedef pthread_t napi_mbt_thread;
static napi_mbt_thread napi_mbt_thread_self(void) { return pthread_self(); }
static bool napi_mbt_same_thread(napi_mbt_thread a, napi_mbt_thread b) { return pthread_equal(a, b) != 0; }
#endif

typedef struct napi_mbt_environment napi_mbt_environment;
typedef struct napi_mbt_resource napi_mbt_resource;
typedef struct napi_mbt_arguments napi_mbt_arguments;
typedef struct napi_mbt_construction {
    int type;
    void *payload;
    bool claimed;
    struct napi_mbt_construction *previous;
} napi_mbt_construction;
struct napi_mbt_resource {
    napi_mbt_environment *owner;
    napi_mbt_resource *next;
    napi_mbt_resource *previous;
    void *payload;
    napi_ref reference;
    napi_value (*trampoline)(void *, napi_env, napi_mbt_arguments *);
    int kind;
    int type;
    bool disposed;
    bool pending_free;
    bool disposing;
    bool inert_on_dispose;
};
struct napi_mbt_environment {
    napi_env env;
    napi_mbt_thread thread;
    napi_mbt_environment *next;
    napi_mbt_resource *resources;
    bool closing;
    int cleanup_status;
    napi_mbt_construction *construction;
    void *async_context;
    void (*async_close)(napi_mbt_environment *);
    bool cleanup_requested;
};

static napi_mbt_environment *napi_mbt_environments = NULL;
static napi_mbt_environment *napi_mbt_active = NULL;
static bool napi_mbt_initialized = false;
static int napi_mbt_environment_count = 0;
static int napi_mbt_resource_count = 0;
extern void moonbit_init(void);

static void napi_mbt_unlink_resource(napi_mbt_resource *resource) {
    if (!resource->owner) return;
    if (resource->previous) resource->previous->next = resource->next;
    else resource->owner->resources = resource->next;
    if (resource->next) resource->next->previous = resource->previous;
    resource->owner = NULL;
    resource->next = resource->previous = NULL;
}

static int napi_mbt_dispose_resource(napi_mbt_resource *resource) {
    if (resource->disposed) return napi_ok;
    napi_mbt_environment *owner = resource->owner;
    if (!owner || !napi_mbt_same_thread(owner->thread, napi_mbt_thread_self())) return 1005;
    if (resource->reference) {
        napi_status status = napi_delete_reference(owner->env, resource->reference);
        if (status != napi_ok && !owner->closing) return (int)status;
        if (status != napi_ok) owner->cleanup_status = (int)status;
        resource->reference = NULL;
    }
    resource->disposed = true;
    resource->disposing = true;
    void *payload = resource->payload;
    resource->payload = NULL;
    if (payload) moonbit_decref(payload);
    resource->disposing = false;
    return napi_ok;
}

static void napi_mbt_free_resource(napi_mbt_resource *resource) {
    if (!resource) return;
    napi_mbt_lock();
    if (resource->disposing) {
        resource->pending_free = true;
        napi_mbt_unlock();
        return;
    }
    int status = napi_mbt_dispose_resource(resource);
    if (status != napi_ok) {
        // A MoonBit global may release a callback captured in another environment.
        // Leave the N-API reference for its owner's next entry or cleanup hook.
        resource->pending_free = true;
        napi_mbt_unlock();
        return;
    }
    napi_mbt_unlink_resource(resource);
    napi_mbt_resource_count--;
    free(resource);
    napi_mbt_unlock();
}

static void napi_mbt_flush_resources(napi_mbt_environment *owner) {
    // Re-scan after every decref: finalizers may unlink other resources.
    for (;;) {
        napi_mbt_resource *resource = owner->resources;
        while (resource && (!resource->pending_free || resource->disposing)) resource = resource->next;
        if (!resource) return;
        if (napi_mbt_dispose_resource(resource) != napi_ok) return;
        napi_mbt_free_resource(resource);
    }
}

static void napi_mbt_cleanup_environment(void *data) {
    napi_mbt_lock();
    napi_mbt_environment *owner = (napi_mbt_environment *)data;
    if (owner->async_context) {
        owner->cleanup_requested = true;
        owner->async_close(owner);
        napi_mbt_unlock();
        return;
    }
    napi_mbt_environment *previous = napi_mbt_active;
    napi_mbt_active = owner;
    owner->closing = true;
    napi_mbt_flush_resources(owner);
    while (owner->resources) {
        napi_mbt_resource *resource = owner->resources;
        (void)napi_mbt_dispose_resource(resource);
        if (resource->pending_free || resource->kind == 3) napi_mbt_free_resource(resource);
        else napi_mbt_unlink_resource(resource);
        // Live JS/MoonBit wrappers own the container; their finalizer frees it.
        // No wrapper keeps the environment alive after shutdown.
    }
    napi_mbt_environment **entry = &napi_mbt_environments;
    while (*entry && *entry != owner) entry = &(*entry)->next;
    if (*entry) *entry = owner->next;
    napi_mbt_active = previous == owner ? NULL : previous;
    napi_mbt_environment_count--;
    free(owner);
    napi_mbt_unlock();
}

int napi_mbt_enter(napi_env env, void **previous) {
    napi_mbt_lock();
    napi_mbt_environment *owner = napi_mbt_environments;
    while (owner && owner->env != env) owner = owner->next;
#if NAPI_VERSION >= 3
    if (!owner) {
        owner = (napi_mbt_environment *)calloc(1, sizeof(*owner));
        if (!owner) { napi_mbt_unlock(); return napi_generic_failure; }
        owner->env = env;
        owner->thread = napi_mbt_thread_self();
        napi_status status = napi_add_env_cleanup_hook(env, napi_mbt_cleanup_environment, owner);
        if (status != napi_ok) { free(owner); napi_mbt_unlock(); return (int)status; }
        owner->next = napi_mbt_environments;
        napi_mbt_environments = owner;
        napi_mbt_environment_count++;
    }
#endif
    if (owner && (owner->closing || !napi_mbt_same_thread(owner->thread, napi_mbt_thread_self()))) {
        napi_mbt_unlock();
        return 1005;
    }
    *previous = napi_mbt_active;
    napi_mbt_active = owner;
    if (!napi_mbt_initialized) { moonbit_init(); napi_mbt_initialized = true; }
    if (owner) napi_mbt_flush_resources(owner);
    return napi_ok;
}

void napi_mbt_leave(void *previous) {
    napi_mbt_active = (napi_mbt_environment *)previous;
    napi_mbt_unlock();
}

static napi_mbt_resource *napi_mbt_new_resource(napi_env env, int kind, int type) {
    if (!napi_mbt_active || napi_mbt_active->env != env || napi_mbt_active->closing) return NULL;
    napi_mbt_resource *resource = (napi_mbt_resource *)calloc(1, sizeof(*resource));
    if (!resource) return NULL;
    resource->owner = napi_mbt_active;
    resource->kind = kind;
    resource->type = type;
    resource->next = napi_mbt_active->resources;
    if (resource->next) resource->next->previous = resource;
    napi_mbt_active->resources = resource;
    napi_mbt_resource_count++;
    return resource;
}

static int napi_mbt_check_resource(napi_mbt_resource *resource, napi_env env) {
    if (!resource || resource->disposed || !resource->owner) return 1006;
    if (resource->owner != napi_mbt_active || resource->owner->env != env || !napi_mbt_same_thread(resource->owner->thread, napi_mbt_thread_self())) return 1005;
    if (resource->owner->closing) return 1004;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_live_environments(void) { return napi_mbt_environment_count; }
MOONBIT_FFI_EXPORT int napi_mbt_live_resources(void) { return napi_mbt_resource_count; }
MOONBIT_FFI_EXPORT int napi_mbt_live_resource_kind(int kind) {
    int count = 0;
    for (napi_mbt_environment *env = napi_mbt_environments; env; env = env->next)
        for (napi_mbt_resource *r = env->resources; r; r = r->next)
            if (r->kind == kind) count++;
    return count;
}

static void napi_mbt_native_finalizer(napi_env env, void *data, void *hint) {
    (void)env; (void)hint;
    napi_mbt_free_resource((napi_mbt_resource *)data);
}

// Lookup compares an untrusted napi_unwrap pointer against our own registry
// before dereferencing it. Other addons' wrapped objects are never cast.
static int napi_mbt_find_instance(napi_env env, napi_value value, int type, bool allow_disposed, napi_mbt_resource **result) {
    if (!napi_mbt_active || napi_mbt_active->env != env) return 1005;
    void *pointer = NULL;
    napi_status status = napi_unwrap(env, value, &pointer);
    if (status != napi_ok) return status == napi_pending_exception ? (int)status : 1007;
    napi_mbt_resource *resource = napi_mbt_active->resources;
    while (resource && resource != pointer) resource = resource->next;
    if (!resource || resource->kind != 1 || resource->type != type) return 1007;
    if (!allow_disposed) {
        int checked = napi_mbt_check_resource(resource, env);
        if (checked != napi_ok) return checked;
    }
    *result = resource;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_class_lookup(napi_env env, napi_value value, int type, void **result) {
    napi_mbt_resource *resource = NULL;
    int status = napi_mbt_find_instance(env, value, type, false, &resource);
    if (status == napi_ok) *result = resource;
    return status;
}

// Only called immediately after successful lookup, while holding the lock.
// Return ownership of one reference to the concrete generated MoonBit type.
MOONBIT_FFI_EXPORT void *napi_mbt_class_payload(void *pointer) {
    napi_mbt_resource *resource = (napi_mbt_resource *)pointer;
    moonbit_incref(resource->payload);
    return resource->payload;
}

MOONBIT_FFI_EXPORT int napi_mbt_class_wrap(napi_env env, napi_value receiver, void *payload, int type) {
    napi_mbt_resource *resource = napi_mbt_new_resource(env, 1, type);
    if (!resource) return napi_generic_failure;
    napi_status status = napi_wrap(env, receiver, resource, napi_mbt_native_finalizer, NULL, NULL);
    if (status != napi_ok) { napi_mbt_free_resource(resource); return (int)status; }
    moonbit_incref(payload);
    resource->payload = payload;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_class_dispose(napi_env env, napi_value receiver, int type) {
    napi_mbt_resource *resource = NULL;
    int status = napi_mbt_find_instance(env, receiver, type, true, &resource);
    if (status != napi_ok) return status;
    return napi_mbt_dispose_resource(resource);
}

int napi_mbt_save_constructor(napi_env env, napi_value constructor, int type) {
    napi_mbt_resource *resource = napi_mbt_new_resource(env, 3, type);
    if (!resource) return napi_generic_failure;
    napi_status status = napi_create_reference(env, constructor, 1, &resource->reference);
    if (status != napi_ok) { napi_mbt_free_resource(resource); return (int)status; }
    return napi_ok;
}

int napi_mbt_construct_pending(napi_env env, napi_value receiver, int type, bool *handled) {
    *handled = false;
    if (!napi_mbt_active || napi_mbt_active->env != env) return 1005;
    napi_mbt_construction *pending = napi_mbt_active->construction;
    if (!pending || pending->type != type || pending->claimed) return napi_ok;
    int status = napi_mbt_class_wrap(env, receiver, pending->payload, type);
    if (status == napi_ok) { pending->claimed = true; *handled = true; }
    return status;
}

MOONBIT_FFI_EXPORT int napi_mbt_class_create(napi_env env, void *payload, int type, napi_value *result) {
    if (!napi_mbt_active || napi_mbt_active->env != env) return 1005;
    napi_mbt_resource *constructor = napi_mbt_active->resources;
    while (constructor && !(constructor->kind == 3 && constructor->type == type && !constructor->disposed)) constructor = constructor->next;
    if (!constructor) return 1007;
    napi_value function;
    napi_status status = napi_get_reference_value(env, constructor->reference, &function);
    if (status != napi_ok) return (int)status;
    napi_mbt_construction pending = { type, payload, false, napi_mbt_active->construction };
    napi_mbt_active->construction = &pending;
    status = napi_new_instance(env, function, 0, NULL, result);
    napi_mbt_active->construction = pending.previous;
    if (status != napi_ok) return (int)status;
    return pending.claimed ? napi_ok : napi_generic_failure;
}
#endif

template/napi_classes.mbt:
///|
#borrow(result)
extern "c" fn napi_class_lookup_raw(
  env : NapiEnv,
  value : NapiValue,
  type_id : Int32,
  result : Ref[UnmanagedBuffer],
) -> Int32 = "napi_mbt_class_lookup"

///|
pub fn napi_class_handle(
  env : NapiEnv,
  value : NapiValue,
  type_id : Int32,
) -> UnmanagedBuffer raise NapiError {
  let result = Ref(moonbit_dummy_unmanaged_buffer())
  result_from_status(
    env,
    napi_class_lookup_raw(env, value, type_id, result),
    b"Validating native receiver",
  )
  result.val
}

///|
extern "c" fn napi_class_dispose_raw(
  env : NapiEnv,
  value : NapiValue,
  type_id : Int32,
) -> Int32 = "napi_mbt_class_dispose"

///|
pub fn napi_class_dispose(
  env : NapiEnv,
  value : NapiValue,
  type_id : Int32,
) -> Unit raise NapiError {
  result_from_status(
    env,
    napi_class_dispose_raw(env, value, type_id),
    b"Disposing native receiver",
  )
}

template/napi_callbacks.mbt:
///|
/// An owned reference to a JavaScript function. The reference belongs to its
/// creating environment; dispose is idempotent and GC is a fallback.
pub type NapiCallback

///|
#external
pub type NapiArguments

///|
extern "c" fn napi_callback_empty() -> NapiCallback = "napi_mbt_callback_empty"

///|
#borrow(callback)
extern "c" fn napi_callback_bind(
  env : NapiEnv,
  value : NapiValue,
  callback : NapiCallback,
) -> Int32 = "napi_mbt_callback_bind"

///|
#borrow(callback, result)
extern "c" fn napi_callback_env_raw(
  callback : NapiCallback,
  result : Ref[NapiEnv],
) -> Int32 = "napi_mbt_callback_env"

///|
#borrow(callback, result)
extern "c" fn napi_callback_call_raw(
  callback : NapiCallback,
  args : NapiValue,
  result : Ref[NapiValue],
) -> Int32 = "napi_mbt_callback_call"

///|
#borrow(callback)
extern "c" fn napi_callback_dispose_raw(callback : NapiCallback) -> Int32 = "napi_mbt_callback_dispose"

///|
pub fn NapiCallback::new(
  env : NapiEnv,
  value : NapiValue,
) -> NapiCallback raise NapiError {
  let callback = napi_callback_empty()
  result_from_status(
    env,
    napi_callback_bind(env, value, callback),
    b"Retaining JavaScript callback",
  )
  callback
}

///|
pub fn NapiCallback::environment(
  self : NapiCallback,
) -> NapiEnv raise NapiError {
  let result = Ref(napi_dummy_env())
  let status = napi_callback_env_raw(self, result)
  // The stored environment may already have closed. Do not call N-API with it.
  if status != 0 {
    raise napi_failure(
      status,
      Error,
      if status == 1006 {
        "ERR_NAPI_DISPOSED"
      } else {
        "ERR_NAPI_ENVIRONMENT"
      },
      "Calling callback outside its owning environment",
    )
  }
  result.val
}

///|
extern "c" fn napi_dummy_env() -> NapiEnv = "napi_mbt_dummy_env"

///|
pub fn NapiCallback::call(
  self : NapiCallback,
  args : NapiValue,
) -> NapiValue raise NapiError {
  let env = self.environment()
  let result = Ref(moonbit_dummy_napi_value())
  result_from_status(
    env,
    napi_callback_call_raw(self, args, result),
    b"Calling JavaScript callback",
  )
  result.val
}

///|
pub fn NapiCallback::dispose(self : NapiCallback) -> Unit raise NapiError {
  let status = napi_callback_dispose_raw(self)
  if status != 0 {
    raise napi_failure(
      status,
      Error,
      "ERR_NAPI_ENVIRONMENT",
      "Disposing JavaScript callback",
    )
  }
}

///|
extern "c" fn napi_arguments_length(args : NapiArguments) -> Int32 = "napi_mbt_arguments_length"

///|
#borrow(result)
extern "c" fn napi_arguments_get_raw(
  env : NapiEnv,
  args : NapiArguments,
  index : Int32,
  result : Ref[NapiValue],
) -> Int32 = "napi_mbt_arguments_get"

///|
pub fn NapiArguments::require(
  self : NapiArguments,
  count : Int32,
) -> Unit raise NapiError {
  if napi_arguments_length(self) < count {
    raise napi_failure(
      1,
      TypeError,
      "ERR_NAPI_ARGUMENTS",
      "Missing callback argument",
    )
  }
}

///|
pub fn NapiArguments::get(
  self : NapiArguments,
  env : NapiEnv,
  index : Int32,
) -> NapiValue raise NapiError {
  let result = Ref(moonbit_dummy_napi_value())
  result_from_status(
    env,
    napi_arguments_get_raw(env, self, index, result),
    b"Reading closure argument",
  )
  result.val
}

///|
#borrow(callback, result)
extern "c" fn napi_closure_new_raw(
  env : NapiEnv,
  callback : (NapiEnv, NapiArguments) -> NapiValue,
  trampoline : FuncRef[
    ((NapiEnv, NapiArguments) -> NapiValue, NapiEnv, NapiArguments) -> NapiValue,
  ],
  result : Ref[NapiValue],
) -> Int32 = "napi_mbt_closure_new"

///|
pub fn napi_closure_new(
  env : NapiEnv,
  callback : (NapiEnv, NapiArguments) -> NapiValue,
) -> NapiValue raise NapiError {
  let result = Ref(moonbit_dummy_napi_value())
  result_from_status(
    env,
    napi_closure_new_raw(
      env,
      callback,
      fn(f, env, args) { f(env, args) },
      result,
    ),
    b"Creating MoonBit closure",
  )
  result.val
}

template/napi_callbacks.h:
/* Included after napi_lifecycle.h; all operations run on the owning JS thread. */
typedef struct { napi_mbt_resource *resource; bool borrowed; } napi_mbt_callback_ref;
struct napi_mbt_arguments { size_t count; napi_value *values; };
typedef napi_value (*napi_mbt_trampoline)(void *, napi_env, napi_mbt_arguments *);

static void napi_mbt_callback_finalizer(void *data) {
    napi_mbt_callback_ref *callback = data;
    /* Listener pins borrow a JS-owned container. In particular their MoonBit
     * finalizer can run while environment cleanup decrefs that very closure. */
    if (!callback->borrowed) napi_mbt_free_resource(callback->resource);
}

MOONBIT_FFI_EXPORT void *napi_mbt_callback_empty(void) {
    napi_mbt_callback_ref *callback = moonbit_make_external_object(napi_mbt_callback_finalizer, sizeof(*callback));
    callback->resource = NULL;
    callback->borrowed = false;
    return callback;
}
MOONBIT_FFI_EXPORT napi_env napi_mbt_dummy_env(void) { return NULL; }

/* Box values so references retain primitives (including thrown undefined) too. */
MOONBIT_FFI_EXPORT int napi_mbt_reference_bind(napi_env env, napi_value value, napi_mbt_callback_ref *reference) {
    napi_value box;
    napi_status status = napi_create_array_with_length(env, 1, &box);
    if (status == napi_ok) status = napi_set_element(env, box, 0, value);
    if (status != napi_ok) return (int)status;
    napi_mbt_resource *resource = napi_mbt_new_resource(env, 5, 0);
    if (!resource) return napi_generic_failure;
    status = napi_create_reference(env, box, 1, &resource->reference);
    if (status != napi_ok) { napi_mbt_free_resource(resource); return (int)status; }
    reference->resource = resource;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_reference_get(napi_env env, napi_mbt_callback_ref *reference, napi_value *result) {
    int status = napi_mbt_check_resource(reference->resource, env);
    if (status != napi_ok) return status;
    napi_value box;
    status = napi_get_reference_value(env, reference->resource->reference, &box);
    if (status == napi_ok) status = napi_get_element(env, box, 0, result);
    return status;
}

/* Own the listener payload independently of its JS wrapper. Cleanup can release
 * it without creating JS handles or invoking JS during environment teardown. */
MOONBIT_FFI_EXPORT int napi_mbt_closure_pin(napi_env env, napi_value value, napi_mbt_callback_ref *reference) {
    void *pointer = NULL;
    int status = napi_unwrap(env, value, &pointer);
    if (status != napi_ok) return status;
    napi_mbt_resource *resource = napi_mbt_active->resources;
    while (resource && resource != pointer) resource = resource->next;
    if (!resource || resource->kind != 2) return 1007;
    /* This reference borrows the container; its JS wrapper is retained by a
     * separate NapiReference until the pin has been disposed. */
    reference->resource = resource;
    reference->borrowed = true;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_closure_unpin(napi_mbt_callback_ref *reference) {
    napi_mbt_resource *resource = reference->resource;
    reference->resource = NULL;
    if (!resource) return napi_ok;
    /* After teardown the borrowed pointer may be stale. Compare it against the
     * current owner's registry before touching it. */
    napi_mbt_resource *entry = napi_mbt_active ? napi_mbt_active->resources : NULL;
    while (entry && entry != resource) entry = entry->next;
    return entry ? napi_mbt_dispose_resource(entry) : napi_ok;
}

/* Promise reactions cannot be removed from JS. Drop their MoonBit payload on
 * completion/cancellation, and let a later reaction return undefined safely. */
MOONBIT_FFI_EXPORT int napi_mbt_closure_inert(napi_env env, napi_value value) {
    void *pointer = NULL;
    int status = napi_unwrap(env, value, &pointer);
    if (status != napi_ok) return status;
    napi_mbt_resource *resource = napi_mbt_active->resources;
    while (resource && resource != pointer) resource = resource->next;
    if (!resource || resource->kind != 2) return 1007;
    resource->inert_on_dispose = true;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_owned_reference_dispose(napi_mbt_callback_ref *reference) {
    if (!reference->resource || reference->resource->disposed) return napi_ok;
    if (reference->resource->owner != napi_mbt_active) return 1005;
    return napi_mbt_dispose_resource(reference->resource);
}

MOONBIT_FFI_EXPORT int napi_mbt_take_exception(napi_env env, napi_value *result) {
    return (int)napi_get_and_clear_last_exception(env, result);
}

MOONBIT_FFI_EXPORT int napi_mbt_reference_throw(napi_env env, napi_mbt_callback_ref *reference) {
    bool pending = false;
    napi_status status = napi_is_exception_pending(env, &pending);
    if (status != napi_ok || pending) return (int)status;
    napi_value value;
    int checked = napi_mbt_reference_get(env, reference, &value);
    return checked == napi_ok ? (int)napi_throw(env, value) : checked;
}

MOONBIT_FFI_EXPORT int napi_mbt_callback_bind(napi_env env, napi_value value, napi_mbt_callback_ref *callback) {
    napi_valuetype type;
    napi_status status = napi_typeof(env, value, &type);
    if (status != napi_ok) return (int)status;
    if (type != napi_function) return napi_function_expected;
    napi_mbt_resource *resource = napi_mbt_new_resource(env, 4, 0);
    if (!resource) return napi_generic_failure;
    status = napi_create_reference(env, value, 1, &resource->reference);
    if (status != napi_ok) { napi_mbt_free_resource(resource); return (int)status; }
    callback->resource = resource;
    return napi_ok;
}

MOONBIT_FFI_EXPORT int napi_mbt_callback_env(napi_mbt_callback_ref *callback, napi_env *result) {
    if (!napi_mbt_active) return 1005;
    int status = napi_mbt_check_resource(callback->resource, napi_mbt_active->env);
    if (status == napi_ok) *result = napi_mbt_active->env;
    return status;
}

MOONBIT_FFI_EXPORT int napi_mbt_callback_dispose(napi_mbt_callback_ref *callback) {
    if (!callback->resource || callback->resource->disposed) return napi_ok;
    napi_env env;
    int status = napi_mbt_callback_env(callback, &env);
    return status == napi_ok ? napi_mbt_dispose_resource(callback->resource) : status;
}

MOONBIT_FFI_EXPORT int napi_mbt_callback_call(napi_mbt_callback_ref *callback, napi_value args, napi_value *result) {
    napi_env env;
    int checked = napi_mbt_callback_env(callback, &env);
    if (checked != napi_ok) return checked;
    napi_value function, receiver;
    uint32_t count;
    napi_status status = napi_get_reference_value(env, callback->resource->reference, &function);
    if (status != napi_ok) return (int)status;
    status = napi_get_undefined(env, &receiver);
    if (status != napi_ok) return (int)status;
    status = napi_get_array_length(env, args, &count);
    if (status != napi_ok) return (int)status;
    if (count > SIZE_MAX / sizeof(napi_value)) return napi_invalid_arg;
    napi_value *values = count ? malloc(sizeof(*values) * count) : NULL;
    if (count && !values) return napi_generic_failure;
    for (uint32_t i = 0; i < count; ++i) {
        status = napi_get_element(env, args, i, &values[i]);
        if (status != napi_ok) { free(values); return (int)status; }
    }
    status = napi_call_function(env, receiver, function, count, values, result);
    free(values);
    return (int)status;
}

MOONBIT_FFI_EXPORT int napi_mbt_arguments_length(napi_mbt_arguments *args) { return (int)args->count; }
MOONBIT_FFI_EXPORT int napi_mbt_arguments_get(napi_env env, napi_mbt_arguments *args, int index, napi_value *result) {
    if (index < 0) return napi_invalid_arg;
    if ((size_t)index >= args->count) return napi_get_undefined(env, result);
    *result = args->values[index];
    return napi_ok;
}

extern int napi_mbt_throw_status(napi_env, int, int, const char *, const char *);
static napi_value napi_mbt_closure_error(napi_env env, int status) {
    const char *code = status == 1006 ? "ERR_NAPI_DISPOSED" : status == 1007 ? "ERR_NAPI_RECEIVER" : "ERR_NAPI_CALLBACK";
    (void)napi_mbt_throw_status(env, status, status == 1007 ? 1 : 0, code, "Calling MoonBit closure");
    return NULL;
}

static napi_value napi_mbt_closure_call(napi_env env, napi_callback_info info) {
    void *previous;
    int checked = napi_mbt_enter(env, &previous);
    if (checked != napi_ok) return napi_mbt_closure_error(env, checked);
    napi_mbt_arguments args = {0, NULL};
    napi_mbt_resource *resource = NULL;
    napi_value result = NULL;
    checked = napi_get_cb_info(env, info, &args.count, NULL, NULL, (void **)&resource);
    if (checked != napi_ok) goto done;
    checked = napi_mbt_check_resource(resource, env);
    if (checked == 1006 && resource->inert_on_dispose) {
        checked = napi_get_undefined(env, &result);
        goto done;
    }
    if (checked != napi_ok) goto done;
    if (args.count > INT32_MAX || args.count > SIZE_MAX / sizeof(napi_value)) { checked = napi_invalid_arg; goto done; }
    args.values = args.count ? malloc(sizeof(napi_value) * args.count) : NULL;
    if (args.count && !args.values) { checked = napi_generic_failure; goto done; }
    checked = napi_get_cb_info(env, info, &args.count, args.values, NULL, NULL);
    if (checked != napi_ok) goto done;
    // FuncRef arguments are borrowed. Pin the closure across the call, including
    // reentrant dispose which clears resource->payload, then release our pin.
    void *payload = resource->payload;
    moonbit_incref(payload);
    result = resource->trampoline(payload, env, &args);
    moonbit_decref(payload);
done:
    free(args.values);
    if (checked != napi_ok) result = napi_mbt_closure_error(env, checked);
    napi_mbt_leave(previous);
    return result;
}

static napi_value napi_mbt_closure_dispose(napi_env env, napi_callback_info info) {
    void *previous;
    int checked = napi_mbt_enter(env, &previous);
    if (checked != napi_ok) return napi_mbt_closure_error(env, checked);
    napi_value receiver, result = NULL;
    void *pointer = NULL;
    checked = napi_get_cb_info(env, info, NULL, NULL, &receiver, NULL);
    if (checked == napi_ok) checked = napi_unwrap(env, receiver, &pointer);
    napi_mbt_resource *resource = napi_mbt_active->resources;
    while (resource && resource != pointer) resource = resource->next;
    if (!resource || resource->kind != 2) checked = 1007;
    if (checked == napi_ok) checked = napi_mbt_dispose_resource(resource);
    if (checked == napi_ok) checked = napi_get_undefined(env, &result);
    if (checked != napi_ok) result = napi_mbt_closure_error(env, checked);
    napi_mbt_leave(previous);
    return result;
}

MOONBIT_FFI_EXPORT int napi_mbt_closure_new(napi_env env, void *callback, napi_mbt_trampoline trampoline, napi_value *result) {
    napi_mbt_resource *resource = napi_mbt_new_resource(env, 2, 0);
    if (!resource) return napi_generic_failure;
    napi_status status = napi_create_function(env, "MoonBitClosure", NAPI_AUTO_LENGTH, napi_mbt_closure_call, resource, result);
    if (status != napi_ok) { napi_mbt_free_resource(resource); return (int)status; }
    status = napi_wrap(env, *result, resource, napi_mbt_native_finalizer, NULL, NULL);
    if (status != napi_ok) { napi_mbt_free_resource(resource); return (int)status; }
    moonbit_incref(callback);
    resource->payload = callback;
    resource->trampoline = trampoline;
    napi_property_descriptor property = {0};
    property.utf8name = "dispose";
    property.method = napi_mbt_closure_dispose;
    status = napi_define_properties(env, *result, 1, &property);
    if (status != napi_ok) (void)napi_mbt_dispose_resource(resource);
    return (int)status;
}

async/napi_async.h:
/* Opaque libuv API declarations from libuv 1.40.0 (MIT; see LIBUV-LICENSE).
 * Allocate with uv_handle_size so no platform struct layout is copied. Node
 * versions supporting N-API 8 provide these APIs in their embedded libuv. */
#include <stdio.h>
typedef struct uv_timer_s uv_timer_t;
typedef struct uv_handle_s uv_handle_t;
typedef struct uv_loop_s uv_loop_t;
extern size_t uv_handle_size(int type);
extern void *uv_handle_get_data(const uv_handle_t *);
extern void uv_handle_set_data(uv_handle_t *, void *);
extern int uv_timer_init(uv_loop_t *, uv_timer_t *);
extern int uv_timer_start(uv_timer_t *, void (*)(uv_timer_t *), uint64_t, uint64_t);
extern int uv_timer_stop(uv_timer_t *);
extern void uv_close(uv_handle_t *, void (*)(uv_handle_t *));

typedef struct {
    napi_mbt_environment *owner;
    uv_timer_t *timer;
    void *state;
    int32_t (*tick)(void *, int32_t);
    napi_async_cleanup_hook_handle cleanup;
    napi_async_context async_context;
    napi_ref async_resource;
    bool closing;
    bool handle_closing;
} napi_mbt_async_context;

static void napi_mbt_async_timer(uv_timer_t *timer);
static void napi_mbt_async_begin_close(napi_mbt_environment *owner);

static void napi_mbt_async_handle_closed(uv_handle_t *handle) {
    napi_mbt_async_context *context = uv_handle_get_data(handle);
    napi_mbt_lock();
    napi_mbt_environment *owner = context->owner;
    napi_mbt_environment *previous = napi_mbt_active;
    napi_mbt_active = owner;
    moonbit_decref(context->state);
    if (context->async_context) {
        napi_status status = napi_async_destroy(owner->env, context->async_context);
        if (status != napi_ok) owner->cleanup_status = status;
    }
    if (context->async_resource) {
        napi_status status = napi_delete_reference(owner->env, context->async_resource);
        if (status != napi_ok) owner->cleanup_status = status;
    }
    owner->async_context = NULL;
    owner->async_close = NULL;
    napi_mbt_active = previous;
    napi_async_cleanup_hook_handle cleanup = context->cleanup;
    free(context->timer);
    free(context);
    if (owner->cleanup_requested) napi_mbt_cleanup_environment(owner);
    if (cleanup) {
        // No JavaScript can be called while an environment is shutting down.
        napi_status status = napi_remove_async_cleanup_hook(cleanup);
        if (status != napi_ok) fprintf(stderr, "napi-mbt: removing async cleanup hook failed (%d)\n", (int)status);
    }
    napi_mbt_unlock();
}

static void napi_mbt_async_timer(uv_timer_t *timer) {
    napi_mbt_async_context *context = uv_handle_get_data((uv_handle_t *)timer);
    napi_mbt_lock();
    napi_mbt_environment *previous = napi_mbt_active;
    napi_mbt_active = context->owner;
    napi_handle_scope scope = NULL;
    napi_callback_scope callback_scope = NULL;
    if (!context->closing) {
        napi_status status = napi_open_handle_scope(context->owner->env, &scope);
        napi_value resource, runnable;
        if (status == napi_ok) status = napi_get_reference_value(context->owner->env, context->async_resource, &resource);
        /* Opening a callback scope does not check whether Node can still enter
         * JS. During Worker::terminate, Node drains native async work before
         * running cleanup hooks, so our timer can fire in that interval. Boolean
         * coercion of our own plain resource cannot execute user code, but does
         * perform the Node-API execution-state check before opening the scope. */
        if (status == napi_ok) status = napi_coerce_to_bool(context->owner->env, resource, &runnable);
        if (status == napi_ok) status = napi_open_callback_scope(context->owner->env, resource, context->async_context, &callback_scope);
        if (status != napi_ok) { context->closing = true; context->owner->closing = true; }
    }
    int delay = context->tick(context->state, context->closing);
    if (delay == -2) {
        context->handle_closing = true;
        uv_close((uv_handle_t *)timer, napi_mbt_async_handle_closed);
    } else if (delay >= 0) {
        int status = uv_timer_start(timer, napi_mbt_async_timer, delay ? (uint64_t)delay : 1, 0);
        if (status != 0) fprintf(stderr, "napi-mbt: async timer failed (%d)\n", status);
    }
    // Arm before draining microtasks: a reentrant export can schedule an earlier
    // tick, which must not be overwritten by the previously computed delay.
    if (callback_scope) {
        napi_status status = napi_close_callback_scope(context->owner->env, callback_scope);
        if (status != napi_ok) context->owner->cleanup_status = status;
    }
    if (scope) {
        napi_status status = napi_close_handle_scope(context->owner->env, scope);
        if (status != napi_ok) context->owner->cleanup_status = status;
    }
    napi_mbt_active = previous;
    napi_mbt_unlock();
}

static void napi_mbt_async_begin_close(napi_mbt_environment *owner) {
    napi_mbt_async_context *context = owner->async_context;
    if (context->handle_closing || context->closing) return;
    context->closing = true;
    owner->closing = true;
    int status = uv_timer_start(context->timer, napi_mbt_async_timer, 0, 0);
    if (status != 0) fprintf(stderr, "napi-mbt: async shutdown timer failed (%d)\n", status);
}

static void napi_mbt_async_cleanup(napi_async_cleanup_hook_handle handle, void *data) {
    napi_mbt_async_context *context = data;
    napi_mbt_lock();
    context->cleanup = handle;
    napi_mbt_async_begin_close(context->owner);
    napi_mbt_unlock();
}

MOONBIT_FFI_EXPORT int napi_mbt_async_has(napi_env env) {
    return napi_mbt_active && napi_mbt_active->env == env && napi_mbt_active->async_context != NULL;
}
MOONBIT_FFI_EXPORT void *napi_mbt_async_get(napi_env env) {
    (void)env;
    napi_mbt_async_context *context = napi_mbt_active->async_context;
    moonbit_incref(context->state);
    return context->state;
}
MOONBIT_FFI_EXPORT int napi_mbt_async_attach(napi_env env, void *state, int32_t (*tick)(void *, int32_t)) {
    if (!napi_mbt_active || napi_mbt_active->env != env || napi_mbt_active->closing) return 1004;
    uv_loop_t *event_loop;
    napi_status status = napi_get_uv_event_loop(env, &event_loop);
    if (status != napi_ok) return (int)status;
    napi_mbt_async_context *context = calloc(1, sizeof(*context));
    if (!context) return napi_generic_failure;
    napi_value resource, name;
    status = napi_create_object(env, &resource);
    if (status == napi_ok) status = napi_create_string_utf8(env, "napi-mbt:async", NAPI_AUTO_LENGTH, &name);
    if (status == napi_ok) status = napi_create_reference(env, resource, 1, &context->async_resource);
    if (status == napi_ok) status = napi_async_init(env, resource, name, &context->async_context);
    if (status != napi_ok) {
        if (context->async_resource) (void)napi_delete_reference(env, context->async_resource);
        free(context); return (int)status;
    }
    context->timer = calloc(1, uv_handle_size(13 /* UV_TIMER */));
    if (!context->timer || uv_timer_init(event_loop, context->timer) != 0) {
        (void)napi_async_destroy(env, context->async_context);
        (void)napi_delete_reference(env, context->async_resource);
        free(context->timer); free(context); return napi_generic_failure;
    }
    context->owner = napi_mbt_active;
    context->state = state;
    context->tick = tick;
    moonbit_incref(state);
    uv_handle_set_data((uv_handle_t *)context->timer, context);
    napi_mbt_active->async_context = context;
    napi_mbt_active->async_close = napi_mbt_async_begin_close;
    status = napi_add_async_cleanup_hook(env, napi_mbt_async_cleanup, context, &context->cleanup);
    if (status != napi_ok) {
        context->handle_closing = true;
        uv_close((uv_handle_t *)context->timer, napi_mbt_async_handle_closed);
    }
    return (int)status;
}
MOONBIT_FFI_EXPORT int napi_mbt_async_schedule(napi_env env) {
    if (!napi_mbt_active || napi_mbt_active->env != env || napi_mbt_active->closing) return 1004;
    napi_mbt_async_context *context = napi_mbt_active->async_context;
    return uv_timer_start(context->timer, napi_mbt_async_timer, 0, 0) == 0 ? napi_ok : napi_generic_failure;
}
MOONBIT_FFI_EXPORT int napi_mbt_async_closing(napi_env env) {
    return !napi_mbt_active || napi_mbt_active->env != env || napi_mbt_active->closing;
}
MOONBIT_FFI_EXPORT int napi_mbt_async_promise_create(napi_env env, napi_value executor, napi_value *result) {
    napi_value global, constructor;
    napi_status status = napi_get_global(env, &global);
    if (status == napi_ok) status = napi_get_named_property(env, global, "Promise", &constructor);
    if (status == napi_ok) status = napi_new_instance(env, constructor, 1, &executor, result);
    bool is_promise = false;
    if (status == napi_ok) status = napi_is_promise(env, *result, &is_promise);
    if (status == napi_ok && !is_promise) status = napi_invalid_arg;
    return (int)status;
}
MOONBIT_FFI_EXPORT napi_env napi_mbt_current_env(void) {
    return napi_mbt_active ? napi_mbt_active->env : NULL;
}
MOONBIT_FFI_EXPORT int napi_mbt_async_owns(napi_env env) {
    return napi_mbt_active && napi_mbt_active->env == env;
}

MOONBIT_FFI_EXPORT int napi_mbt_promise_then(napi_env env, napi_value promise, napi_value resolve, napi_value reject) {
    napi_value then, result;
    napi_status status = napi_get_named_property(env, promise, "then", &then);
    napi_value args[] = { resolve, reject };
    if (status == napi_ok) status = napi_call_function(env, promise, then, 2, args, &result);
    return (int)status;
}

MOONBIT_FFI_EXPORT int napi_mbt_signal_get(napi_env env, napi_value object, const char *name, napi_value *result) {
    return (int)napi_get_named_property(env, object, name, result);
}

MOONBIT_FFI_EXPORT int napi_mbt_signal_listen(napi_env env, napi_value signal, napi_value listener, int add) {
    napi_value function, event, result, options, once;
    napi_status status = napi_get_named_property(env, signal, add ? "addEventListener" : "removeEventListener", &function);
    if (status == napi_ok) status = napi_create_string_utf8(env, "abort", NAPI_AUTO_LENGTH, &event);
    if (status == napi_ok) status = napi_create_object(env, &options);
    if (status == napi_ok) status = napi_get_boolean(env, true, &once);
    if (status == napi_ok) status = napi_set_named_property(env, options, "once", once);
    napi_value args[] = { event, listener, options };
    if (status == napi_ok) status = napi_call_function(env, signal, function, add ? 3 : 2, args, &result);
    return (int)status;
}

MOONBIT_FFI_EXPORT int napi_mbt_abort_reason(napi_env env, napi_value signal, napi_value *result) {
    napi_status status = napi_get_named_property(env, signal, "reason", result);
    napi_valuetype type;
    if (status == napi_ok) status = napi_typeof(env, *result, &type);
    if (status != napi_ok || type != napi_undefined) return (int)status;
    napi_value code, message, name;
    status = napi_create_string_utf8(env, "ABORT_ERR", NAPI_AUTO_LENGTH, &code);
    if (status == napi_ok) status = napi_create_string_utf8(env, "The operation was aborted", NAPI_AUTO_LENGTH, &message);
    if (status == napi_ok) status = napi_create_error(env, code, message, result);
    if (status == napi_ok) status = napi_create_string_utf8(env, "AbortError", NAPI_AUTO_LENGTH, &name);
    if (status == napi_ok) status = napi_set_named_property(env, *result, "name", name);
    return (int)status;
}

MOONBIT_FFI_EXPORT int napi_mbt_stream_factory(napi_env env, int input, napi_value a, napi_value b, napi_value *result) {
  napi_value source, factory, receiver, flag;
  napi_status status = napi_create_string_utf8(env, "// Embedded product runtime. Evaluates to a factory, without global state.\n((input, a, b) => {\n  'use strict';\n  if (input) {\n    let iterator, reader, ended = false;\n    if (a == null) throw new TypeError('Expected AsyncIterable or ReadableStream');\n    const method = a[Symbol.asyncIterator];\n    // Prefer a reader so cancellation can interrupt a pending Web stream read.\n    if (typeof a.getReader === 'function') reader = a.getReader();\n    else if (typeof method === 'function') iterator = method.call(a);\n    else throw new TypeError('Expected AsyncIterable or ReadableStream');\n    return {\n      async next() {\n        if (ended) return {done: true};\n        const result = await (reader ? reader.read() : iterator.next());\n        if (!result || typeof result !== 'object') throw new TypeError('Invalid iterator result');\n        const done = Boolean(result.done);\n        return done ? {done: true} : {done: false, value: result.value};\n      },\n      async close() {\n        if (ended) return;\n        ended = true;\n        try {\n          if (reader) await reader.cancel();\n          else if (typeof iterator.return === 'function') await iterator.return();\n        } finally {\n          if (reader) reader.releaseLock();\n          reader = iterator = a = null;\n        }\n      }\n    };\n  }\n  let next = a, close = b, ended = false, chain = Promise.resolve(), closing;\n  a = b = null;\n  let mode = null;\n  const done = () => ({done: true, value: undefined});\n  const finish = () => {\n    if (closing) return closing;\n    ended = true;\n    const release = close;\n    next = close = null;\n    closing = release ? Promise.resolve(release()).then(done) : Promise.resolve(done());\n    return closing;\n  };\n  const read = () => {\n    const result = chain.then(async () => {\n      if (ended) return done();\n      try {\n        const result = await next();\n        if (result.done) { ended = true; next = close = null; }\n        return result;\n      } catch (error) {\n        // Native production failures already run the common close path.\n        ended = true; next = close = null;\n        throw error;\n      }\n    });\n    chain = result.catch(() => {});\n    return result;\n  };\n  return {\n    [Symbol.asyncIterator]() {\n      if (mode !== null) throw new TypeError('Stream already has a consumption chain');\n      mode = 'iterator'; return this;\n    },\n    next() {\n      if (mode === 'stream') return Promise.reject(new TypeError('Stream already has a consumption chain'));\n      if (mode === null) mode = 'manual';\n      return read();\n    },\n    return() { return finish(); },\n    async throw(error) { await finish(); throw error; },\n    toReadableStream({signal} = {}) {\n      if (mode !== null) throw new TypeError('Stream already has a consumption chain');\n      if (typeof ReadableStream !== 'function') throw new Error('Web streams require Node 18 or later');\n      mode = 'stream';\n      let abort, cancelled = false;\n      const detach = () => { if (signal && abort) signal.removeEventListener('abort', abort); };\n      return new ReadableStream({\n        start(controller) {\n          if (!signal) return;\n          abort = () => {\n            cancelled = true; detach();\n            controller.error(signal.reason);\n            finish().catch(() => {});\n          };\n          if (signal.aborted) abort(); else signal.addEventListener('abort', abort, {once: true});\n        },\n        async pull(controller) {\n          try {\n            const result = await read();\n            if (cancelled) return;\n            if (result.done) { detach(); controller.close(); }\n            else controller.enqueue(result.value);\n          } catch (error) { if (!cancelled) { detach(); controller.error(error); } }\n        },\n        cancel() { cancelled = true; detach(); return finish(); }\n      }, {highWaterMark: 0});\n    }\n  };\n})\n", NAPI_AUTO_LENGTH, &source);
  if (status == napi_ok) status = napi_run_script(env, source, &factory);
  if (status == napi_ok) status = napi_get_undefined(env, &receiver);
  if (status == napi_ok) status = napi_get_boolean(env, input != 0, &flag);
  napi_value args[] = { flag, a, b };
  if (status == napi_ok) status = napi_call_function(env, receiver, factory, 3, args, result);
  return (int)status;
}

async/napi_async.mbt:
///|
priv struct NapiAsyncState {
  scheduler : @napi_mbt_async.Loop
  mut cancelled : Bool
}

///|
extern "c" fn napi_async_has(env : NapiEnv) -> Bool = "napi_mbt_async_has"

///|
extern "c" fn napi_async_get(env : NapiEnv) -> NapiAsyncState = "napi_mbt_async_get"

///|
#borrow(state)
extern "c" fn napi_async_attach(env : NapiEnv, state : NapiAsyncState, tick : FuncRef[(NapiAsyncState, Bool) -> Int32]) -> Int32 = "napi_mbt_async_attach"

///|
extern "c" fn napi_async_schedule(env : NapiEnv) -> Int32 = "napi_mbt_async_schedule"

///|
extern "c" fn napi_async_closing(env : NapiEnv) -> Bool = "napi_mbt_async_closing"

///|
extern "c" fn napi_current_env() -> NapiEnv = "napi_mbt_current_env"

///|
pub fn napi_async_spawn(task : async () -> Unit) -> @napi_mbt_async.Task raise {
  napi_async_submit(napi_current_env(), task)
}

///|
fn napi_async_tick(state : NapiAsyncState, closing : Bool) -> Int32 {
  try {
    if closing && !state.cancelled { state.cancelled = true; state.scheduler.cancel_all() }
    let pending = state.scheduler.step()
    if closing && pending == 0 { state.scheduler.close(); -2 } else { state.scheduler.next_wake() }
  } catch {
    error => { eprintln("napi-mbt async scheduler: \{error}"); 2 }
  }
}

///|
fn napi_async_submit(env : NapiEnv, task : async () -> Unit) -> @napi_mbt_async.Task raise {
  if napi_async_closing(env) { raise napi_failure(1004, Error, "ERR_NAPI_ENV_CLOSED", "Starting asynchronous task") }
  let state = if napi_async_has(env) { napi_async_get(env) } else {
    let state = { scheduler: @napi_mbt_async.Loop::new(), cancelled: false }
    errdefer { state.scheduler.close() catch { _ => () } }
    result_from_status(env, napi_async_attach(env, state, fn(state, closing) { napi_async_tick(state, closing) }), b"Attaching async scheduler")
    state
  }
  let handle = state.scheduler.submit(task)
  result_from_status(env, napi_async_schedule(env), b"Scheduling async task")
  handle
}

///|
priv struct NapiAsyncCall {
  env : NapiEnv
  promise : NapiAsyncPromise
  mut task : @napi_mbt_async.Task?
  mut signal : NapiReference?
  mut listener : NapiReference?
  mut cleaned : Bool
  pin : NapiReference
}

///|
// Node-API provides no release operation for an unsettled napi_deferred.
// Own JS resolver references instead so worker teardown can release them
// without entering JavaScript or settling a Promise in a closing environment.
priv struct NapiAsyncPromise {
  mut promise : NapiValue
  mut resolve : NapiCallback?
  mut reject : NapiCallback?
  mut accepting : Bool
  mut settled : Bool
}

///|
#borrow(result)
extern "c" fn napi_async_promise_create(env : NapiEnv, executor : NapiValue, result : Ref[NapiValue]) -> Int32 = "napi_mbt_async_promise_create"

///|
fn NapiAsyncPromise::dispose(self : NapiAsyncPromise) -> Unit {
  let resolve = self.resolve
  let reject = self.reject
  self.resolve = None
  self.reject = None
  self.accepting = false
  self.settled = true
  if resolve is Some(callback) { callback.dispose() catch { _ => () } }
  if reject is Some(callback) { callback.dispose() catch { _ => () } }
}

///|
fn napi_async_promise_new(env : NapiEnv) -> NapiAsyncPromise raise {
  let state : NapiAsyncPromise = { promise: moonbit_dummy_napi_value(), resolve: None, reject: None, accepting: true, settled: false }
  errdefer state.dispose()
  defer { state.accepting = false }
  let executor = napi_closure_new(env, fn(env, args) {
    try {
      if !state.accepting { raise napi_failure(1, TypeError, "ERR_NAPI_PROMISE_EXECUTOR", "Promise executor invoked outside construction") }
      state.accepting = false
      args.require(2)
      state.resolve = Some(NapiCallback::new(env, args.get(env, 0)))
      state.reject = Some(NapiCallback::new(env, args.get(env, 1)))
      set_Unit(env, ())
    } catch { error => { throw_napi_error(env, error); moonbit_dummy_napi_value() } }
  })
  let result = Ref(moonbit_dummy_napi_value())
  result_from_status(env, napi_async_promise_create(env, executor, result), b"Constructing async Promise")
  if state.resolve is None || state.reject is None { raise napi_failure(1, TypeError, "ERR_NAPI_PROMISE_EXECUTOR", "Promise constructor did not provide resolvers") }
  state.promise = result.val
  state
}

///|
fn NapiAsyncPromise::settle(self : NapiAsyncPromise, env : NapiEnv, value : NapiValue, reject~ : Bool) -> Unit raise {
  if self.settled { raise napi_failure(1, Error, "ERR_NAPI_PROMISE_SETTLED", "Promise has already settled") }
  self.settled = true
  defer self.dispose()
  guard (if reject { self.reject } else { self.resolve }) is Some(callback) else { raise napi_failure(1, Error, "ERR_NAPI_PROMISE_EXECUTOR", "Missing Promise resolver") }
  let args = napi_array_new(env, 1)
  napi_array_set(env, args, 0, value)
  ignore(callback.call(args))
}

///|
#borrow(name, result)
extern "c" fn napi_signal_get_raw(env : NapiEnv, object : NapiValue, name : Bytes, result : Ref[NapiValue]) -> Int32 = "napi_mbt_signal_get"

///|
extern "c" fn napi_signal_listen(env : NapiEnv, signal : NapiValue, listener : NapiValue, add : Bool) -> Int32 = "napi_mbt_signal_listen"

///|
#borrow(result)
extern "c" fn napi_abort_reason(env : NapiEnv, signal : NapiValue, result : Ref[NapiValue]) -> Int32 = "napi_mbt_abort_reason"

///|
#borrow(reference)
extern "c" fn napi_listener_pin(env : NapiEnv, listener : NapiValue, reference : NapiReference) -> Int32 = "napi_mbt_closure_pin"

///|
#borrow(reference)
extern "c" fn napi_listener_unpin(reference : NapiReference) -> Int32 = "napi_mbt_closure_unpin"

///|
fn napi_signal_get(env : NapiEnv, object : NapiValue, name : Bytes) -> NapiValue raise {
  let result = Ref(moonbit_dummy_napi_value())
  result_from_status(env, napi_signal_get_raw(env, object, name, result), b"Reading AbortSignal")
  result.val
}

///|
fn NapiAsyncCall::cleanup(self : NapiAsyncCall) -> Unit {
  if self.cleaned { return }
  self.cleaned = true
  self.promise.dispose()
  // Clear fields before invoking JS: removeEventListener may reenter the addon.
  let signal = self.signal
  let listener = self.listener
  self.signal = None
  self.listener = None
  self.task = None
  if !napi_async_closing(self.env) && signal is Some(signal) && listener is Some(listener) {
    try {
      result_from_status(self.env, napi_signal_listen(self.env, signal.get(self.env), listener.get(self.env), false), b"Removing abort listener")
    } catch { _ => () } // Preserve the original settlement; still release payload.
  }
  ignore(napi_listener_unpin(self.pin))
  if listener is Some(reference) { reference.dispose() catch { _ => () } }
  if signal is Some(reference) { reference.dispose() catch { _ => () } }
}

///|
fn NapiAsyncCall::reject(self : NapiAsyncCall, error : Error) -> Unit {
  if !self.promise.settled && !napi_async_closing(self.env) {
    try { self.promise.settle(self.env, napi_error_value(self.env, error), reject=true) }
    catch { error => { eprintln("napi-mbt: rejecting async call: " + (error : Error).to_string()) } }
  }
  self.cleanup()
}

///|
fn NapiAsyncCall::abort(self : NapiAsyncCall) -> Unit {
  if self.promise.settled { return }
  let task = self.task
  try {
    if self.signal is Some(signal) {
      let reason = Ref(moonbit_dummy_napi_value())
      result_from_status(self.env, napi_abort_reason(self.env, signal.get(self.env), reason), b"Reading abort reason")
      self.promise.settle(self.env, reason.val, reject=true)
    }
  } catch { error => self.reject(error) }
  if task is Some(task) {
    task.cancel() catch { error => { eprintln("napi-mbt: cancelling task: \{error}") } }
    ignore(napi_async_schedule(self.env))
  }
  self.cleanup()
}

///|
fn NapiAsyncCall::listen(self : NapiAsyncCall, options : NapiValue) -> Unit raise {
  if napi_is_nullish(self.env, options) { return }
  napi_require_object(self.env, options)
  let signal = napi_signal_get(self.env, options, b"signal")
  if napi_is_nullish(self.env, signal) { return }
  napi_require_object(self.env, signal)
  self.signal = Some(NapiReference::new(self.env, signal))
  if get_Bool(self.env, napi_signal_get(self.env, signal, b"aborted")) { self.abort(); return }
  let listener = napi_closure_new(self.env, (env, _) => { self.abort(); set_Unit(env, ()) catch { _ => moonbit_dummy_napi_value() } })
  self.listener = Some(NapiReference::new(self.env, listener))
  result_from_status(self.env, napi_listener_pin(self.env, listener, self.pin), b"Retaining abort listener")
  result_from_status(self.env, napi_signal_listen(self.env, signal, listener, true), b"Adding abort listener")
  if !self.promise.settled && get_Bool(self.env, napi_signal_get(self.env, signal, b"aborted")) { self.abort() }
}

///|
fn napi_async_call_new(env : NapiEnv) -> NapiAsyncCall raise {
  { env, promise: napi_async_promise_new(env), task: None, signal: None, listener: None, cleaned: false, pin: napi_reference_empty() }
}

///|
fn NapiAsyncCall::start(self : NapiAsyncCall, work : async () -> NapiValue) -> Unit raise {
  if self.promise.settled { return }
  self.task = Some(napi_async_submit(self.env, () => {
    defer self.cleanup()
    if self.promise.settled || napi_async_closing(self.env) { return }
    try {
      let result = work()
      if !self.promise.settled && !napi_async_closing(self.env) { self.promise.settle(self.env, result, reject=false) }
    } catch { error => self.reject(error) }
  }))
}

///|
/// A typed Promise owned by the creating Node environment. Waiting is cancellable;
/// JS rejection values retain identity. A completed value may be awaited again.
pub struct NapiJsPromise[T] {
  priv env : NapiEnv
  priv mut result : Result[T, Error]?
  priv mut promise : NapiReference?
  priv mut handlers : Array[(NapiReference, NapiReference)]
  priv mut waiters : Array[(Int, @napi_mbt_async.Task)]
  priv mut next_id : Int
  priv mut closed : Bool
}

///|
extern "c" fn napi_promise_then(env : NapiEnv, promise : NapiValue, resolve : NapiValue, reject : NapiValue) -> Int = "napi_mbt_promise_then"

///|
extern "c" fn napi_reaction_inert(env : NapiEnv, value : NapiValue) -> Int = "napi_mbt_closure_inert"

///|
extern "c" fn napi_async_owns(env : NapiEnv) -> Bool = "napi_mbt_async_owns"

///|
fn[T] NapiJsPromise::release_handlers(self : NapiJsPromise[T]) -> Unit {
  let handlers = self.handlers
  let promise = self.promise
  self.handlers = []
  self.promise = None
  for (pin, reference) in handlers {
    ignore(napi_listener_unpin(pin))
    reference.dispose() catch { _ => () }
  }
  if promise is Some(reference) { reference.dispose() catch { _ => () } }
}

///|
fn[T] NapiJsPromise::wake(self : NapiJsPromise[T]) -> Unit {
  let waiters = self.waiters
  self.waiters = []
  for (_, task) in waiters { task.wake() catch { _ => () } }
  if napi_async_has(self.env) && !napi_async_closing(self.env) { ignore(napi_async_schedule(self.env)) }
}

///|
/// Release a pending subscription; late JS reactions become inert. Idempotent.
pub fn[T] NapiJsPromise::dispose(self : NapiJsPromise[T]) -> Unit raise NapiError {
  if !napi_async_owns(self.env) { raise napi_failure(1005, Error, "ERR_NAPI_ENVIRONMENT", "Disposing a Promise outside its owning environment") }
  self.close_owned()
}

///|
fn[T] NapiJsPromise::close_owned(self : NapiJsPromise[T]) -> Unit {
  if self.closed { return }
  self.closed = true
  self.result = None
  self.release_handlers()
  self.wake()
}

///|
pub async fn[T] NapiJsPromise::wait(self : NapiJsPromise[T]) -> T {
  if napi_async_closing(self.env) { raise napi_failure(1005, Error, "ERR_NAPI_ENVIRONMENT", "Promise belongs to another or closed environment") }
  if self.closed { raise napi_failure(1006, Error, "ERR_NAPI_DISPOSED", "Promise subscription is closed") }
  let id = self.next_id
  self.next_id += 1
  if self.result is None {
    self.waiters.push((id, napi_async_get(self.env).scheduler.current_task()))
  }
  defer {
    self.waiters = self.waiters.filter(waiter => waiter.0 != id)
    if self.result is None && self.waiters.is_empty() { self.close_owned() }
  }
  while self.result is None && !self.closed { @napi_mbt_async.suspend() }
  match self.result {
    Some(Ok(value)) => value
    Some(Err(error)) => raise error
    None => raise napi_failure(1006, Error, "ERR_NAPI_DISPOSED", "Promise subscription is closed")
  }
}

///|
fn[T] get_NapiJsPromise(env : NapiEnv, value : NapiValue, convert : (NapiEnv, NapiValue) -> T raise) -> NapiJsPromise[T] raise {
  let valid = Ref(false)
  result_from_status(env, napi_is_promise(env, value, valid), b"Reading JavaScript Promise")
  if !valid.val { raise napi_failure(1, TypeError, "ERR_NAPI_PROMISE", "Expected JavaScript Promise") }
  let state : NapiJsPromise[T] = { env, result: None, promise: Some(NapiReference::new(env, value)), handlers: [], waiters: [], next_id: 0, closed: false }
  errdefer state.close_owned()
  fn reaction(reject : Bool) -> NapiValue raise {
    let callback = napi_closure_new(env, fn(env, args) {
      if !state.closed && state.result is None {
        state.result = Some(try {
          let value = args.get(env, 0)
          if reject { raise NapiError::JavaScriptException(NapiReference::new(env, value)) }
          Ok(convert(env, value))
        } catch { error => Err(error) })
        state.release_handlers()
        state.wake()
      }
      set_Unit(env, ()) catch { _ => moonbit_dummy_napi_value() }
    })
    let reference = NapiReference::new(env, callback)
    let pin = napi_reference_empty()
    result_from_status(env, napi_reaction_inert(env, callback), b"Preparing Promise reaction")
    result_from_status(env, napi_listener_pin(env, callback, pin), b"Retaining Promise reaction")
    state.handlers.push((pin, reference))
    callback
  }
  let resolve = reaction(false)
  let reject = reaction(true)
  result_from_status(env, napi_promise_then(env, value, resolve, reject), b"Subscribing to JavaScript Promise")
  state
}

///|
priv struct NapiStreamRead[T] {
  mut result : Result[T?, Error]?
  task : @napi_mbt_async.Task
}

///|
/// A demand-driven iterator owned by one Node environment. close is idempotent.
pub struct NapiAsyncIterator[T] {
  priv env : NapiEnv
  priv produce : async () -> T?
  priv finish : async () -> Unit
  priv mut closed : Bool
  priv mut finished : Result[Unit, Error]?
  priv mut queue : Array[NapiStreamRead[T]]
  priv mut active : NapiStreamRead[T]?
  priv mut producer : @napi_mbt_async.Task?
  priv mut lifetime : @napi_mbt_async.Task?
  priv mut waiters : Array[@napi_mbt_async.Task]
  priv mut pins : Array[(NapiReference, NapiReference)]
}

///|
fn[T] NapiAsyncIterator::check(self : NapiAsyncIterator[T]) -> Unit raise {
  if !napi_async_owns(self.env) { raise napi_failure(1005, Error, "ERR_NAPI_ENVIRONMENT", "Stream belongs to another environment") }
}

///|
fn[T] NapiAsyncIterator::notify(self : NapiAsyncIterator[T]) -> Unit {
  let tasks = self.waiters
  self.waiters = []
  for task in tasks { task.wake() catch { _ => () } }
  if !napi_async_closing(self.env) { ignore(napi_async_schedule(self.env)) }
}

///|
fn[T] NapiAsyncIterator::begin_close(self : NapiAsyncIterator[T]) -> Unit {
  if self.closed { return }
  self.closed = true
  let tasks = self.queue
  self.queue = []
  if self.active is Some(request) { tasks.push(request) }
  for request in tasks {
    if request.result is None { request.result = Some(Ok(None)) }
    request.task.wake() catch { _ => () }
  }
  if self.producer is Some(task) { task.cancel() catch { _ => () } }
  if self.lifetime is Some(task) { task.wake() catch { _ => () } }
  self.notify()
}

///|
pub fn[T] NapiAsyncIterator::new(produce : async () -> T?, close : async () -> Unit) -> NapiAsyncIterator[T] raise {
  let env = napi_current_env()
  let state : NapiAsyncIterator[T] = { env, produce, finish: close, closed: false, finished: None, queue: [], active: None, producer: None, lifetime: None, waiters: [], pins: [] }
  state.lifetime = Some(napi_async_submit(env, () => {
    defer @napi_mbt_async.protect(() => {
      state.begin_close()
      state.finished = Some(try { (state.finish)(); Ok(()) } catch { error => Err(error) })
      let pins = state.pins
      state.pins = []
      for (pin, reference) in pins { ignore(napi_listener_unpin(pin)); reference.dispose() catch { _ => () } }
      state.lifetime = None
      state.notify()
    })
    while !state.closed { @napi_mbt_async.suspend() }
  }))
  state
}

///|
pub async fn[T] NapiAsyncIterator::next(self : NapiAsyncIterator[T]) -> T? {
  self.check()
  if self.closed { return None }
  let request : NapiStreamRead[T] = { result: None, task: napi_async_get(self.env).scheduler.current_task() }
  self.queue.push(request)
  defer { if request.result is None { self.begin_close() } }
  if self.producer is None {
    self.producer = Some(napi_async_submit(self.env, () => {
      defer { self.producer = None; self.active = None }
      while !self.closed && !self.queue.is_empty() {
        let request = self.queue[0]
        self.queue = self.queue[1:].to_owned()
        self.active = Some(request)
        let result = try { Ok((self.produce)()) } catch { error => Err(error) }
        if request.result is None { request.result = Some(result) }
        request.task.wake() catch { _ => () }
        self.active = None
        if result is Ok(None) || result is Err(_) { self.begin_close() }
      }
    }))
  }
  while request.result is None { @napi_mbt_async.suspend() }
  match request.result.unwrap() { Ok(None) => { self.close(); None }; Ok(value) => value; Err(error) => raise error }
}

///|
pub async fn[T] NapiAsyncIterator::close(self : NapiAsyncIterator[T]) -> Unit {
  self.check()
  self.begin_close()
  while self.finished is None {
    self.waiters.push(napi_async_get(self.env).scheduler.current_task())
    @napi_mbt_async.suspend()
  }
  match self.finished.unwrap() { Ok(_) => (); Err(error) => raise error }
}

///|
#borrow(result)
extern "c" fn napi_stream_factory(env : NapiEnv, input : Bool, a : NapiValue, b : NapiValue, result : Ref[NapiValue]) -> Int = "napi_mbt_stream_factory"

///|
fn napi_stream_make(env : NapiEnv, input : Bool, a : NapiValue, b : NapiValue) -> NapiValue raise {
  let result = Ref(moonbit_dummy_napi_value())
  result_from_status(env, napi_stream_factory(env, input, a, b, result), b"Creating stream adapter")
  result.val
}

///|
fn[T] get_NapiAsyncIterator(env : NapiEnv, value : NapiValue, convert : (NapiEnv, NapiValue) -> T raise) -> NapiAsyncIterator[T] raise {
  let normalized = napi_stream_make(env, true, value, napi_null(env))
  let next = NapiCallback::new(env, napi_field_get(env, normalized, "next", true))
  errdefer { next.dispose() catch { _ => () } }
  let close = NapiCallback::new(env, napi_field_get(env, normalized, "close", true))
  errdefer { close.dispose() catch { _ => () } }
  NapiAsyncIterator::new(() => {
    if napi_async_closing(env) { raise napi_failure(1004, Error, "ERR_NAPI_ENV_CLOSED", "Reading stream during shutdown") }
    let promise = get_NapiJsPromise(env, next.call(napi_array_new(env, 0)), fn(env, value) {
      napi_require_object(env, value)
      if get_Bool(env, napi_field_get(env, value, "done", true)) { None } else { Some(convert(env, napi_field_get(env, value, "value", true))) }
    })
    promise.wait()
  }, () => {
    defer { next.dispose() catch { _ => () }; close.dispose() catch { _ => () } }
    if !napi_async_closing(env) {
      let promise = get_NapiJsPromise(env, close.call(napi_array_new(env, 0)), fn(_, _) { () })
      promise.wait()
    }
  })
}

///|
fn[T] set_NapiAsyncIterator(env : NapiEnv, value : NapiAsyncIterator[T], convert : (NapiEnv, T) -> NapiValue raise) -> NapiValue raise {
  value.check()
  fn callback(closing : Bool) -> NapiValue raise {
    let callback = napi_closure_new(env, fn(env, _) {
      try {
        let call = napi_async_call_new(env)
        call.start(() => {
          let item = if closing { value.close(); None } else { value.next() }
          if napi_async_closing(env) { raise napi_failure(1004, Error, "ERR_NAPI_ENV_CLOSED", "Completing stream during shutdown") }
          let result = napi_object_new(env)
          napi_field_set(env, result, "done", set_Bool(env, item is None))
          if item is Some(item) {
            try { napi_field_set(env, result, "value", convert(env, item)) }
            catch { error => { value.begin_close(); raise error } }
          }
          result
        })
        call.promise.promise
      } catch { error => { throw_napi_error(env, error); moonbit_dummy_napi_value() } }
    })
    let pin = napi_reference_empty()
    let reference = NapiReference::new(env, callback)
    result_from_status(env, napi_listener_pin(env, callback, pin), b"Retaining stream callback")
    value.pins.push((pin, reference))
    callback
  }
  let next = callback(false)
  let close = callback(true)
  napi_stream_make(env, false, next, close)
}

