template/napi_owned_binary.h:
#ifndef NAPI_MBT_OWNED_BINARY_H
#define NAPI_MBT_OWNED_BINARY_H

/* Owner-thread-only conversion. Both directions copy; no JS backing pointer or
 * JS handle is stored in a MoonBit value. The arrays may outlive this call. */
static size_t napi_mbt_binary_width(int kind) {
    return kind == 1 || kind == -1 ? 1 : kind == 8 ? 8 : 4;
}

static void *napi_mbt_binary_allocate(int kind, int32_t length) {
    switch (kind) {
    case 5: case 6: return moonbit_make_int32_array_raw(length);
    case 7: return moonbit_make_float_array_raw(length);
    case 8: return moonbit_make_double_array_raw(length);
    default: return moonbit_make_bytes_raw(length);
    }
}

static void *napi_mbt_read_owned_binary(
    napi_env env, napi_value value, int kind, int32_t *error) {
    void *data = NULL;
    size_t length = 0;
    napi_status status = napi_ok;
#if NAPI_VERSION >= 7
    napi_value backing = value;
    bool valid = false, detached = false;
    if (kind != -1) {
        status = napi_is_typedarray(env, value, &valid);
        if (status != napi_ok) goto done;
        if (!valid) { status = napi_invalid_arg; goto done; }
        napi_typedarray_type type;
        size_t offset;
        status = napi_get_typedarray_info(env, value, &type, &length, &data, &backing, &offset);
        if (status != napi_ok) goto done;
        if ((int)type != kind) { status = napi_invalid_arg; goto done; }
    }
    /* napi_is_arraybuffer explicitly excludes SharedArrayBuffer, including a
     * shared store behind an otherwise valid typed view. Never copy racing data. */
    status = napi_is_arraybuffer(env, backing, &valid);
    if (status != napi_ok) goto done;
    if (!valid) { status = napi_invalid_arg; goto done; }
    status = napi_is_detached_arraybuffer(env, backing, &detached);
    if (status != napi_ok) goto done;
    if (detached) { *error = 1001; return napi_mbt_binary_allocate(kind, 0); }
    if (kind == -1) {
        status = napi_get_arraybuffer_info(env, backing, &data, &length);
        if (status != napi_ok) goto done;
    }
    if (length > INT_MAX || length > SIZE_MAX / napi_mbt_binary_width(kind)) {
        *error = 1002;
        return napi_mbt_binary_allocate(kind, 0);
    }
    if (length && data == NULL) { status = napi_invalid_arg; goto done; }
done:
#else
    (void)env; (void)value;
    status = napi_generic_failure;
#endif
    *error = (int32_t)status;
    void *result = napi_mbt_binary_allocate(kind, status == napi_ok ? (int32_t)length : 0);
    if (status == napi_ok && length) memcpy(result, data, length * napi_mbt_binary_width(kind));
    return result;
}

static int napi_mbt_write_owned_binary(
    napi_env env, const void *array, int kind, napi_value *result) {
    size_t length = (size_t)Moonbit_array_length(array);
    size_t width = napi_mbt_binary_width(kind);
    if (length > SIZE_MAX / width) return 1002;
    void *data = NULL;
    napi_value backing;
    napi_status status = napi_create_arraybuffer(env, length * width, &data, &backing);
    if (status != napi_ok) return (int)status;
    if (length) memcpy(data, array, length * width);
    if (kind == -1) { *result = backing; return (int)napi_ok; }
    return (int)napi_create_typedarray(env, (napi_typedarray_type)kind, length, backing, 0, result);
}

#define NAPI_MBT_BINARY_API(tag, type, kind) \
MOONBIT_FFI_EXPORT type *moonbit_napi_read_##tag(napi_env env, napi_value value, int32_t *status) { \
    return (type *)napi_mbt_read_owned_binary(env, value, kind, status); \
} \
MOONBIT_FFI_EXPORT int moonbit_napi_write_##tag(napi_env env, const type *data, napi_value *result) { \
    return napi_mbt_write_owned_binary(env, data, kind, result); \
}

NAPI_MBT_BINARY_API(Uint8Array, uint8_t, 1)
NAPI_MBT_BINARY_API(Int32Array, int32_t, 5)
NAPI_MBT_BINARY_API(Uint32Array, uint32_t, 6)
NAPI_MBT_BINARY_API(Float32Array, float, 7)
NAPI_MBT_BINARY_API(Float64Array, double, 8)
NAPI_MBT_BINARY_API(ArrayBuffer, uint8_t, -1)
#undef NAPI_MBT_BINARY_API
#endif

async/native_tasks.mbt:
///|
priv type NapiNativeTaskHandle

///|
#borrow(name, input, status)
extern "c" fn napi_native_start(env : NapiEnv, name : Bytes, input : Bytes, status : Ref[Int]) -> NapiNativeTaskHandle = "napi_mbt_native_start"

///|
#borrow(handle)
extern "c" fn napi_native_close(handle : NapiNativeTaskHandle) -> Unit = "napi_mbt_native_close"

///|
#borrow(handle)
extern "c" fn napi_native_status(handle : NapiNativeTaskHandle) -> Int = "napi_mbt_native_status"

///|
#borrow(handle)
extern "c" fn napi_native_output(handle : NapiNativeTaskHandle) -> Bytes = "napi_mbt_native_output"

///|
#borrow(handle)
extern "c" fn napi_native_error(handle : NapiNativeTaskHandle, code : Bool) -> Bytes = "napi_mbt_native_error"

///|
/// Invoke a task registered in napi-mbt.json. Input and output are C-owned copies
/// while running; cancellation requests cooperative termination and releases the
/// caller immediately. The native work retains its storage until it exits.
pub async fn napi_native_task(name : String, input : Bytes) -> Bytes {
  if name.contains("\u0000") { raise napi_failure(1, TypeError, "ERR_NAPI_NATIVE_NAME", "Invalid native task name") }
  let env = napi_current_env()
  let status = Ref(0)
  let handle = napi_native_start(env, @utf8.encode(name), input, status)
  defer napi_native_close(handle)
  result_from_status(env, status.val, b"Starting registered native task")
  while napi_native_status(handle) == 0 { @napi_mbt_tasks.sleep(1) }
  match napi_native_status(handle) {
    1 => napi_native_output(handle)
    3 => raise napi_failure(11, Error, "ERR_NAPI_NATIVE_CANCELLED", "Native task cancelled")
    _ => raise napi_failure(9, Error, @utf8.decode_lossy(napi_native_error(handle, true)), @utf8.decode_lossy(napi_native_error(handle, false)))
  }
}

template/napi_native_task.h:
#ifndef NAPI_MBT_NATIVE_TASK_H
#define NAPI_MBT_NATIVE_TASK_H
#include <stddef.h>
#include <stdint.h>
#define NAPI_MBT_TASK_ABI_VERSION 1
#ifdef __cplusplus
extern "C" {
#endif
/* ABI 1: called on a Node worker thread. The context and input are borrowed
 * until the task returns. Do not retain them, call JS, or touch MoonBit values.
 * result/error copy their data immediately. Submit exactly one result or error.
 * C++ entry points must catch every exception before returning across this ABI. */
typedef struct napi_mbt_task_context napi_mbt_task_context;
typedef void (*napi_mbt_task_function)(napi_mbt_task_context *);
uint32_t napi_mbt_task_abi_version(void);
const uint8_t *napi_mbt_task_input(napi_mbt_task_context *, size_t *length);
int napi_mbt_task_cancelled(napi_mbt_task_context *);
int napi_mbt_task_result(napi_mbt_task_context *, const void *, size_t length);
int napi_mbt_task_error(napi_mbt_task_context *, const char *code, const char *message);
#ifdef __cplusplus
}
#endif
#endif

template/napi_native_task_runtime.h:
#ifndef NAPI_MBT_NATIVE_TASK_RUNTIME_H
#define NAPI_MBT_NATIVE_TASK_RUNTIME_H
#include <moonbit.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include "napi_native_task.h"
#if NAPI_VERSION < 8
#error Native tasks require N-API 8 asynchronous cleanup
#endif
#ifdef _WIN32
#include <windows.h>
typedef volatile LONG napi_mbt_task_atomic;
static void napi_mbt_task_cancel_store(napi_mbt_task_atomic *v) { InterlockedExchange(v, 1); }
static int napi_mbt_task_cancel_load(napi_mbt_task_atomic *v) { return InterlockedCompareExchange(v, 0, 0) != 0; }
#else
#include <stdatomic.h>
typedef atomic_int napi_mbt_task_atomic;
static void napi_mbt_task_cancel_store(napi_mbt_task_atomic *v) { atomic_store(v, 1); }
static int napi_mbt_task_cancel_load(napi_mbt_task_atomic *v) { return atomic_load(v); }
#endif

struct napi_mbt_task_context {
    /* Only cancellation is shared. Execute owns the output until complete runs.
     * The work queue publishes that output to complete. All other state and
     * refcounts are owner-thread-only; there are no MoonBit/JS references here. */
    napi_mbt_task_atomic cancelled;
    uint8_t *input, *output;
    size_t input_length, output_length;
    char *code, *message;
    int submitted, allocation_failed;
    napi_env env;
    napi_async_work work;
    napi_async_cleanup_hook_handle cleanup;
    napi_mbt_task_function execute;
    int refs, done, closing;
};
typedef struct { napi_mbt_task_context *context; } napi_mbt_task_handle;

uint32_t napi_mbt_task_abi_version(void) { return NAPI_MBT_TASK_ABI_VERSION; }
const uint8_t *napi_mbt_task_input(napi_mbt_task_context *c, size_t *length) {
    if (length) *length = c->input_length;
    return c->input;
}
int napi_mbt_task_cancelled(napi_mbt_task_context *c) { return napi_mbt_task_cancel_load(&c->cancelled); }
int napi_mbt_task_result(napi_mbt_task_context *c, const void *data, size_t length) {
    if (c->submitted || length > INT_MAX || (length && !data)) return 0;
    c->submitted = 1;
    c->output = malloc(length ? length : 1);
    if (!c->output) { c->allocation_failed = 1; return 0; }
    if (length) memcpy(c->output, data, length);
    c->output_length = length;
    return 1;
}
static char *napi_mbt_task_string(const char *s) {
    size_t n = strlen(s) + 1;
    char *result = malloc(n);
    if (result) memcpy(result, s, n);
    return result;
}
int napi_mbt_task_error(napi_mbt_task_context *c, const char *code, const char *message) {
    if (c->submitted) return 0;
    c->submitted = 1;
    c->code = napi_mbt_task_string(code ? code : "ERR_NAPI_NATIVE_TASK");
    c->message = napi_mbt_task_string(message ? message : "Native task failed");
    if (!c->code || !c->message) { c->allocation_failed = 1; return 0; }
    return 1;
}
static void napi_mbt_task_release(napi_mbt_task_context *c) {
    if (--c->refs) return;
    free(c->input); free(c->output); free(c->code); free(c->message); free(c);
}
static void napi_mbt_task_cancel(napi_mbt_task_context *c) {
    if (c->done) return;
    napi_mbt_task_cancel_store(&c->cancelled);
    if (c->work) (void)napi_cancel_async_work(c->env, c->work);
}
static void napi_mbt_task_finalize(void *data) {
    napi_mbt_task_handle *handle = data;
    napi_mbt_task_context *c = handle->context;
    handle->context = NULL;
    if (c) { napi_mbt_task_cancel(c); napi_mbt_task_release(c); }
}
static void napi_mbt_task_execute(napi_env env, void *data) {
    (void)env;
    napi_mbt_task_context *c = data;
    if (!napi_mbt_task_cancelled(c)) c->execute(c);
}
static void napi_mbt_task_complete(napi_env env, napi_status status, void *data) {
    napi_mbt_task_context *c = data;
    if (status != napi_ok) napi_mbt_task_cancel_store(&c->cancelled);
    c->done = 1;
    (void)napi_delete_async_work(env, c->work);
    c->work = NULL;
    napi_async_cleanup_hook_handle cleanup = c->cleanup;
    c->cleanup = NULL;
    /* No JS is invoked, including during teardown. Keep the cleanup hook until
     * the actual worker has exited, even after the caller has been cancelled. */
    if (cleanup) (void)napi_remove_async_cleanup_hook(cleanup);
    napi_mbt_task_release(c);
}
static void napi_mbt_task_cleanup(napi_async_cleanup_hook_handle hook, void *data) {
    napi_mbt_task_context *c = data;
    c->cleanup = hook;
    c->closing = 1;
    napi_mbt_task_cancel(c);
}

/* Generated in this translation unit. Lookup cannot be supplied by JS. */
static napi_mbt_task_function napi_mbt_task_lookup(const char *name);

MOONBIT_FFI_EXPORT napi_mbt_task_handle *napi_mbt_native_start(
    napi_env env, const char *name, const uint8_t *input, int32_t *error) {
    napi_mbt_task_handle *handle = moonbit_make_external_object(napi_mbt_task_finalize, sizeof(*handle));
    handle->context = NULL;
    napi_mbt_task_function execute = napi_mbt_task_lookup(name);
    *error = napi_invalid_arg;
    if (!execute) return handle;
    napi_mbt_task_context *c = calloc(1, sizeof(*c));
    *error = napi_generic_failure;
    if (!c) return handle;
#ifndef _WIN32
    atomic_init(&c->cancelled, 0);
#endif
    c->refs = 1; c->env = env; c->execute = execute;
    c->input_length = (size_t)Moonbit_array_length(input);
    c->input = malloc(c->input_length ? c->input_length : 1);
    if (!c->input) { napi_mbt_task_release(c); return handle; }
    if (c->input_length) memcpy(c->input, input, c->input_length);
    napi_value resource;
    napi_status status = napi_create_string_utf8(env, name, NAPI_AUTO_LENGTH, &resource);
    if (status == napi_ok) status = napi_create_async_work(env, NULL, resource, napi_mbt_task_execute, napi_mbt_task_complete, c, &c->work);
    if (status == napi_ok) status = napi_add_async_cleanup_hook(env, napi_mbt_task_cleanup, c, &c->cleanup);
    if (status == napi_ok) status = napi_queue_async_work(env, c->work);
    *error = (int32_t)status;
    if (status != napi_ok) {
        if (c->cleanup) (void)napi_remove_async_cleanup_hook(c->cleanup);
        if (c->work) (void)napi_delete_async_work(env, c->work);
        napi_mbt_task_release(c);
        return handle;
    }
    c->refs++; /* work + returned MoonBit handle; only the owner updates refs */
    handle->context = c;
    return handle;
}
MOONBIT_FFI_EXPORT void napi_mbt_native_close(napi_mbt_task_handle *handle) { napi_mbt_task_finalize(handle); }
MOONBIT_FFI_EXPORT int32_t napi_mbt_native_status(napi_mbt_task_handle *handle) {
    napi_mbt_task_context *c = handle->context;
    if (!c || c->closing) return 3;
    if (!c->done) return 0;
    if (napi_mbt_task_cancelled(c)) return 3;
    return c->allocation_failed || c->code || !c->submitted ? 2 : 1;
}
MOONBIT_FFI_EXPORT moonbit_bytes_t napi_mbt_native_output(napi_mbt_task_handle *handle) {
    napi_mbt_task_context *c = handle->context;
    int32_t length = c && c->done && c->output ? (int32_t)c->output_length : 0;
    moonbit_bytes_t bytes = moonbit_make_bytes(length, 0);
    if (length) memcpy(bytes, c->output, (size_t)length);
    return bytes;
}
MOONBIT_FFI_EXPORT moonbit_bytes_t napi_mbt_native_error(napi_mbt_task_handle *handle, int32_t code) {
    napi_mbt_task_context *c = handle->context;
    const char *s = code ? "ERR_NAPI_NATIVE_TASK" : "Native task did not produce a result";
    if (c && c->done) {
        if (c->allocation_failed) s = code ? "ERR_NAPI_NATIVE_MEMORY" : "Native task allocation failed";
        else if (code && c->code) s = c->code;
        else if (!code && c->message) s = c->message;
    }
    size_t length = strlen(s);
    moonbit_bytes_t bytes = moonbit_make_bytes((int32_t)length, 0);
    if (length) memcpy(bytes, s, length);
    return bytes;
}
#endif

template/napi_worker_lifecycle.h:
#ifndef NAPI_MBT_WORKER_LIFECYCLE_H
#define NAPI_MBT_WORKER_LIFECYCLE_H
#include <stdlib.h>
#include <stdint.h>
#ifdef _WIN32
#include <windows.h>
#else
#include <pthread.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <unistd.h>
#if defined(__linux__)
#include <sys/syscall.h>
#endif
#endif

/* A cleanup hook holds a native process identity independently of JS events.
 * No MoonBit state or JS is touched by cleanup/finalization. */
typedef struct napi_mbt_worker_watch {
    napi_env env;
    int env_hooked;
    napi_async_cleanup_hook_handle async_hook;
    int async_hooked;
    int cleanup_refs;
    struct napi_mbt_worker_watch *next;
#ifdef _WIN32
    HANDLE process;
#else
    pid_t pid;
    int pidfd;
#endif
} napi_mbt_worker_watch;
static napi_mbt_worker_watch *napi_mbt_worker_registry = NULL;
#ifdef _WIN32
static INIT_ONCE napi_mbt_worker_registry_once = INIT_ONCE_STATIC_INIT;
static CRITICAL_SECTION napi_mbt_worker_registry_lock;
static BOOL CALLBACK napi_mbt_worker_registry_init(PINIT_ONCE once, PVOID param, PVOID *context) {
    (void)once; (void)param; (void)context;
    InitializeCriticalSection(&napi_mbt_worker_registry_lock);
    return TRUE;
}
static void napi_mbt_worker_lock(void) {
    InitOnceExecuteOnce(&napi_mbt_worker_registry_once, napi_mbt_worker_registry_init, NULL, NULL);
    EnterCriticalSection(&napi_mbt_worker_registry_lock);
}
static void napi_mbt_worker_unlock(void) { LeaveCriticalSection(&napi_mbt_worker_registry_lock); }
#else
static pthread_mutex_t napi_mbt_worker_registry_lock = PTHREAD_MUTEX_INITIALIZER;
static void napi_mbt_worker_lock(void) { (void)pthread_mutex_lock(&napi_mbt_worker_registry_lock); }
static void napi_mbt_worker_unlock(void) { (void)pthread_mutex_unlock(&napi_mbt_worker_registry_lock); }
#endif
static void napi_mbt_worker_register(napi_mbt_worker_watch *watch) {
    napi_mbt_worker_lock();
    watch->next = napi_mbt_worker_registry;
    napi_mbt_worker_registry = watch;
    napi_mbt_worker_unlock();
}
static napi_mbt_worker_watch *napi_mbt_worker_take(uintptr_t raw) {
    napi_mbt_worker_watch *result = NULL;
    napi_mbt_worker_watch **link;
    napi_mbt_worker_lock();
    for (link = &napi_mbt_worker_registry; *link; link = &(*link)->next) {
        if ((uintptr_t)*link == raw) {
            result = *link;
            *link = result->next;
            break;
        }
    }
    napi_mbt_worker_unlock();
    return result;
}
static void napi_mbt_worker_close(napi_mbt_worker_watch *watch, int terminate) {
#ifdef _WIN32
    if (watch->process) {
        if (terminate && WaitForSingleObject(watch->process, 0) == WAIT_TIMEOUT)
            (void)TerminateProcess(watch->process, 1);
        CloseHandle(watch->process);
        watch->process = NULL;
    }
#else
    if (watch->pid > 0 && terminate) {
#if defined(__linux__) && defined(SYS_pidfd_send_signal)
        if (watch->pidfd >= 0) {
            (void)syscall(SYS_pidfd_send_signal, watch->pidfd, SIGKILL, NULL, 0);
        } else {
            /* WNOWAIT never steals Node/libuv's child exit status. After Node
             * reaps a child ECHILD prevents signalling an unrelated process. */
            siginfo_t info = {0};
            if (waitid(P_PID, (id_t)watch->pid, &info, WEXITED | WNOHANG | WNOWAIT) == 0 && info.si_pid == 0)
                (void)kill(watch->pid, SIGKILL);
        }
#elif defined(__APPLE__)
        /* Node owns the child wait status on macOS.  A cleanup hook only
         * tracks the process created by this pool, so a direct kill avoids
         * waitid(ECHILD) races with libuv's child watcher. */
        (void)kill(watch->pid, SIGKILL);
#else
        {
            /* WNOWAIT never steals Node/libuv's child exit status. After Node
             * reaps a child ECHILD prevents signalling an unrelated process. */
            siginfo_t info = {0};
            if (waitid(P_PID, (id_t)watch->pid, &info, WEXITED | WNOHANG | WNOWAIT) == 0 && info.si_pid == 0)
                (void)kill(watch->pid, SIGKILL);
        }
#endif
    }
    if (watch->pidfd >= 0) close(watch->pidfd);
    watch->pidfd = -1;
    watch->pid = 0;
#endif
}
static void napi_mbt_worker_release(napi_mbt_worker_watch *watch) {
    if (--watch->cleanup_refs == 0) free(watch);
}
