///|
pub struct Scheduler {
  mut coro_id : Int
  mut curr_coro : Coroutine?
  run_later : @deque.Deque[Coroutine]
  all_coros : Set[Coroutine]
}

///|
let scheduler : Ref[Scheduler] = Ref(embedded_new_scheduler())

///|
pub fn current_coroutine() -> Coroutine {
  scheduler.val.curr_coro.unwrap()
}

///|
pub fn has_immediately_ready_task() -> Bool {
  !scheduler.val.run_later.is_empty()
}

///|
/// Perform a new rousd of scheduling by running all ready coroutines.
/// While running these coroutines, new coroutines may get waken or spawned,
/// these new coroutines will *not* get executed in this run of `reschedule`.
/// This give the event loop a chance to check of completed IO operations
/// and prevent starvation, even when there is always immediately ready coroutine.
pub fn reschedule() -> Unit {
  let n = scheduler.val.run_later.length()
  for _ in 0..<n {
    guard scheduler.val.run_later.pop_front() is Some(coro) else { break }
    coro.ready = false
    guard coro.state is Suspend(cont) else {  }
    coro.state = Running
    let last_coro = scheduler.val.curr_coro
    scheduler.val.curr_coro = Some(coro)
    if coro.cancelled && !coro.shielded {
      cont(Cancelled)
    } else {
      cont(Continue)
    }
    scheduler.val.curr_coro = last_coro
  }
}

///|
pub fn all_coroutines() -> Set[Coroutine] {
  scheduler.val.all_coros
}

///|
pub fn embedded_new_scheduler() -> Scheduler {
  { coro_id: 0, curr_coro: None, run_later: Deque([]), all_coros: Set([]) }
}

///|
pub fn embedded_swap_scheduler(next : Scheduler) -> Scheduler {
  let previous = scheduler.val
  scheduler.val = next
  previous
}

