MOONBIT_FFI_EXPORT
void *moonbitlang_async_make_job(
  int32_t size,
  void (*free)(void*),
  int32_t (*worker)(void*, int32_t*),
  int32_t (*cancel_handler)(void*)
) {
  struct job *job = (struct job*)malloc(size + sizeof(struct job));
  job->ret = 0;
